const SIMS={};

function simLabels(id,lvl){
  // A localized page injects window.SIM_LABELS_OVERRIDE so sliders and pills speak
  // its language; the SPA and English pages fall through to the baked set.
  var O=(typeof window!=='undefined')&&window.SIM_LABELS_OVERRIDE;
  if(O&&O[id]&&O[id][lvl])return O[id][lvl];
  return (SIM_LABELS[id]||{})[lvl]||{};
}

function newEl(tag,cls,id){const e=document.createElement(tag);if(cls)e.className=cls;if(id)e.id=id;return e;}

function mkCanvas(container, W, H){
  const dpr=window.devicePixelRatio||1;
  const wrap=newEl('div','sim-canvas-wrap');
  wrap.style.width=W+'px'; wrap.style.height=H+'px';
  const c=document.createElement('canvas');
  c.width=W*dpr; c.height=H*dpr;
  c.style.width=W+'px'; c.style.height=H+'px';
  const ctx=c.getContext('2d');
  ctx.scale(dpr,dpr);
  wrap.appendChild(c);
  container.appendChild(wrap);
  return{canvas:c,ctx,W,H,dpr};
}

function mkCtrl(container){
  const d=newEl('div','sim-controls');
  container.appendChild(d);
  return d;
}

function mkPills(container){const d=newEl('div','sim-pills');container.appendChild(d);return d;}

function pill(lbl){
  const d=newEl('div','spill');d.innerHTML=lbl+': <b>-</b>';
  return{el:d,set(v){d.querySelector('b').textContent=v}};
}

function mkBtn(txt,pri=false,clr=''){
  const b=newEl('button','cbtn'+(pri?' pri':''));
  b.textContent=txt;
  if(pri&&clr)b.style.background=clr;
  return b;
}

function mkRange(ctrl,lbl,min,max,val,step,clr){
  const w=newEl('div','rng-wrap'); const top=newEl('div','rng-top');
  const l=newEl('span','rng-lbl');l.textContent=lbl;
  const v=newEl('span','rng-v');v.textContent=val;if(clr)v.style.color=clr;
  top.appendChild(l);top.appendChild(v);
  const inp=document.createElement('input');inp.type='range';
  // step MUST be set before value: while step is still the default 1, the
  // browser snaps value onto the min+k*1 grid (Star Mass 2 became 2.5), and
  // the label then disagrees with the physics.
  inp.min=min;inp.max=max;inp.step=step||1;inp.value=val;
  w.appendChild(top);w.appendChild(inp);
  ctrl.appendChild(w);
  inp.addEventListener('input',()=>{v.textContent=parseFloat(inp.value).toFixed(step<1?2:0);});
  return{inp,v,get val(){return+inp.value}};
}

function getSimWidth(container){
  // Prefer the container's own laid-out width. Inside the modal the sim tab is
  // display:none at build time so the container measures 0 — there we fall back
  // to #pbody. On a standalone page (no #pbody) the container is visible, so its
  // clientWidth is correct and the fallback is skipped.
  let w=container&&container.clientWidth||0;
  if(!w){
    const pb=document.getElementById('pbody');
    if(pb){
      const cs=getComputedStyle(pb);
      const pad=parseFloat(cs.paddingLeft||0)+parseFloat(cs.paddingRight||0);
      w=(pb.clientWidth||0)-pad;
    }
  }
  w=w||500;
  return Math.min(w-4,820);
}

function stopSims(){
  for(const k in SIMS){
    const s=SIMS[k];
    if(s.raf) cancelAnimationFrame(s.raf);
    if(s.timer) clearTimeout(s.timer);
    if(s.int) clearInterval(s.int);
    delete SIMS[k];
  }
}

