function simSeasons(container,color,lvl){
  const C=(typeof color==='string'&&color[0]==='#')?color:'#f59e0b';
  window.SIMS=window.SIMS||{};
  if(SIMS.seasons&&SIMS.seasons.raf)cancelAnimationFrame(SIMS.seasons.raf);
  const W=getSimWidth(container),H=280;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('seasons',lvl);
  const pN=pill(L.nh),pS=pill(L.sh);
  pRow.appendChild(pN.el);pRow.appendChild(pS.el);
  const rM=mkRange(ctrl,L.month,1,12,6,1,color);
  const St=SIMS.seasons={raf:null};
  const cx=W/2,cy=H/2,ox=Math.min(W*0.33,155),oy=Math.min(H*0.34,84),tilt=23.5*Math.PI/180;
  const MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const NSEAS=['Winter','Winter','Spring','Spring','Spring','Summer','Summer','Summer','Autumn','Autumn','Autumn','Winter'];
  const SSEAS=['Summer','Summer','Autumn','Autumn','Autumn','Winter','Winter','Winter','Spring','Spring','Spring','Summer'];
  function frame(){
    const m=rM.val,mi=Math.max(0,Math.min(11,(m-1)|0)),phi=Math.PI+((m-6)/12)*Math.PI*2;
    ctx.clearRect(0,0,W,H);
    const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#0a0e1a');bg.addColorStop(1,'#05070f');
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.strokeStyle='rgba(255,255,255,0.14)';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(cx,cy,ox,oy,0,0,Math.PI*2);ctx.stroke();
    const sg=ctx.createRadialGradient(cx,cy,3,cx,cy,42);sg.addColorStop(0,'rgba(255,214,90,0.95)');sg.addColorStop(1,'rgba(255,214,90,0)');
    ctx.fillStyle=sg;ctx.beginPath();ctx.arc(cx,cy,42,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ffd24a';ctx.beginPath();ctx.arc(cx,cy,15,0,Math.PI*2);ctx.fill();
    const ex=cx+ox*Math.cos(phi),ey=cy+oy*Math.sin(phi),er=17;
    const sdx=cx-ex,sdy=cy-ey,sl=Math.hypot(sdx,sdy)||1,ux=sdx/sl,uy=sdy/sl;
    ctx.save();ctx.beginPath();ctx.arc(ex,ey,er,0,Math.PI*2);ctx.clip();
    ctx.fillStyle='#0f2744';ctx.fillRect(ex-er,ey-er,er*2,er*2);
    ctx.fillStyle='#3b82f6';ctx.beginPath();ctx.arc(ex+ux*er*0.55,ey+uy*er*0.55,er,0,Math.PI*2);ctx.fill();
    ctx.restore();
    ctx.strokeStyle='rgba(255,255,255,0.5)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(ex,ey,er,0,Math.PI*2);ctx.stroke();
    const axx=Math.sin(tilt),axy=-Math.cos(tilt);
    ctx.strokeStyle='#e5e7eb';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(ex-axx*er*1.35,ey-axy*er*1.35);ctx.lineTo(ex+axx*er*1.35,ey+axy*er*1.35);ctx.stroke();
    ctx.fillStyle='#ef4444';ctx.beginPath();ctx.arc(ex+axx*er*1.35,ey+axy*er*1.35,2.6,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(MON[mi],ex,ey+er+16);ctx.textAlign='left';
    pN.set(NSEAS[mi]);pS.set(SSEAS[mi]);
    St.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simBalance(container,color,lvl){
  const C=(typeof color==='string'&&color[0]==='#')?color:'#10b981';
  window.SIMS=window.SIMS||{};
  if(SIMS.balancing&&SIMS.balancing.raf)cancelAnimationFrame(SIMS.balancing.raf);
  const W=getSimWidth(container),H=290;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('balancing',lvl);
  const pBal=pill(L.bal),pChk=pill(L.check);
  pRow.appendChild(pBal.el);pRow.appendChild(pChk.el);
  const RX=[
   {L:[{f:'CH4',a:{C:1,H:4}},{f:'O2',a:{O:2}}],R:[{f:'CO2',a:{C:1,O:2}},{f:'H2O',a:{H:2,O:1}}]},
   {L:[{f:'H2',a:{H:2}},{f:'O2',a:{O:2}}],R:[{f:'H2O',a:{H:2,O:1}}]},
   {L:[{f:'N2',a:{N:2}},{f:'H2',a:{H:2}}],R:[{f:'NH3',a:{N:1,H:3}}]}
  ];
  const sliders=[];
  for(let i=0;i<4;i++)sliders.push(mkRange(ctrl,'-',1,8,1,1,color));
  const wraps=ctrl.querySelectorAll('.rng-wrap'),labs=[];
  for(let i=0;i<4;i++)labs.push(wraps[i].querySelector('.rng-lbl'));
  const bNext=mkBtn(L.next,true,color);ctrl.appendChild(bNext);
  let cur=0;
  const St=SIMS.balancing={raf:null};
  function species(){return RX[cur].L.concat(RX[cur].R);}
  function loadRx(){const sp=species();for(let i=0;i<4;i++){if(i<sp.length){wraps[i].style.display='';labs[i].textContent=sp[i].f;sliders[i].inp.value=1;sliders[i].v.textContent='1';}else{wraps[i].style.display='none';}}}
  bNext.addEventListener('click',function(){cur=(cur+1)%RX.length;loadRx();});
  loadRx();
  function atomColor(e){return e==='H'?'#94a3b8':e==='O'?'#ef4444':e==='C'?'#334155':e==='N'?'#3b82f6':'#a3a3a3';}
  function drawMol(mx,my,sp){
    const atoms=[];for(const e in sp.a){for(let k=0;k<sp.a[e];k++)atoms.push(e);}
    const n=atoms.length;
    for(let i=0;i<n;i++){
      const ang=(i/n)*Math.PI*2,rr=n>1?10:0,ax=mx+Math.cos(ang)*rr,ay=my+Math.sin(ang)*rr;
      ctx.fillStyle=atomColor(atoms[i]);ctx.beginPath();ctx.arc(ax,ay,7,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='rgba(255,255,255,0.95)';ctx.font='bold 8px system-ui';ctx.textAlign='center';ctx.fillText(atoms[i],ax,ay+3);
    }
    ctx.textAlign='left';
  }
  function frame(){
    ctx.clearRect(0,0,W,H);
    const sp=species(),nL=RX[cur].L.length,coefs=sp.map(function(s,i){return sliders[i].val;});
    const elem={};
    for(let i=0;i<sp.length;i++){const s=sp[i],co=coefs[i],side=i<nL?0:1;for(const e in s.a){if(!elem[e])elem[e]=[0,0];elem[e][side]+=co*s.a[e];}}
    const bal=Object.keys(elem).every(function(e){return elem[e][0]===elem[e][1];});
    const slotW=(W-30)/sp.length,y1=58;
    for(let i=0;i<sp.length;i++){
      const mx=18+slotW*i+slotW/2;
      ctx.fillStyle=C;ctx.font='bold 16px system-ui';ctx.textAlign='right';ctx.fillText(coefs[i],mx-20,y1+4);ctx.textAlign='left';
      drawMol(mx,y1,sp[i]);
      ctx.fillStyle='rgba(120,120,120,0.95)';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText(sp[i].f,mx,y1+26);ctx.textAlign='left';
      if(i<sp.length-1){const sx=18+slotW*(i+1);ctx.fillStyle='rgba(120,120,120,0.9)';ctx.font='17px system-ui';ctx.textAlign='center';ctx.fillText(i===nL-1?'→':'+',sx,y1+5);ctx.textAlign='left';}
    }
    let tx=26,ty=H-74;ctx.font='13px system-ui';ctx.textAlign='left';
    for(const e in elem){const l=elem[e][0],r=elem[e][1],ok=l===r;ctx.fillStyle=ok?'#16a34a':'#dc2626';ctx.fillText(e+':  '+l+(ok?'  =  ':'  ≠  ')+r,tx,ty);ty+=21;if(ty>H-14){ty=H-74;tx+=130;}}
    if(bal){ctx.fillStyle='#16a34a';ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillText('✓ Balanced!',W-90,H-26);ctx.textAlign='left';}
    pBal.set(bal?'Yes':'No');pChk.set(bal?'all atoms match':'counts differ');
    St.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simPunnett(container,color,lvl){
  const C=(typeof color==='string'&&color[0]==='#')?color:'#c026d3';
  window.SIMS=window.SIMS||{};
  SIMS.punnett={raf:null,t0:0};
  const W=getSimWidth(container),H=310;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('punnett',lvl);
  const pPh=pill(L.pheno),pGe=pill(L.geno);
  pRow.appendChild(pPh.el);pRow.appendChild(pGe.el);
  const GENO=['AA','Aa','aa'];
  let g1=1,g2=1;
  const b1=mkBtn(L.p1+': Aa',true,color);ctrl.appendChild(b1);
  const b2=mkBtn(L.p2+': Aa',true,color);ctrl.appendChild(b2);
  function alleles(g){return GENO[g].split('');}
  const St=SIMS.punnett;St.t0=performance.now();
  const clamp01=v=>v<0?0:v>1?1:v;
  const ease=p=>1-Math.pow(1-p,3);
  function chip(x,y,r,letter,dom,a){
    ctx.globalAlpha=a;
    const g=ctx.createRadialGradient(x-r*0.4,y-r*0.4,1,x,y,r);
    g.addColorStop(0,'rgba(255,255,255,0.55)');g.addColorStop(0.5,dom?C:'#94a3b8');g.addColorStop(1,dom?C:'#94a3b8');
    ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.font='bold '+Math.round(r*1.15)+'px system-ui';ctx.textAlign='center';ctx.lineJoin='round';
    ctx.strokeStyle='rgba(30,20,40,0.55)';ctx.lineWidth=2.6;ctx.strokeText(letter,x,y+r*0.4);
    ctx.fillStyle='#fff';ctx.fillText(letter,x,y+r*0.4);
    ctx.globalAlpha=1;
  }
  // Phenotype made visible: a flower that is actually coloured or actually white.
  function flower(x,y,r,dom){
    const petal=dom?C:'#e2e8f0';
    for(let k=0;k<5;k++){const a=-Math.PI/2+k*Math.PI*2/5;
      ctx.beginPath();ctx.ellipse(x+Math.cos(a)*r*0.6,y+Math.sin(a)*r*0.6,r*0.44,r*0.31,a,0,Math.PI*2);
      ctx.fillStyle=petal;ctx.fill();ctx.strokeStyle='rgba(30,30,40,0.14)';ctx.lineWidth=1;ctx.stroke();}
    ctx.beginPath();ctx.arc(x,y,r*0.3,0,Math.PI*2);ctx.fillStyle=dom?'#fde68a':'#cbd5e1';ctx.fill();
  }
  function frame(){
    const p=clamp01((performance.now()-St.t0)/1500);
    const a1=alleles(g1),a2=alleles(g2);
    ctx.clearRect(0,0,W,H);
    const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#fdf6ff');bg.addColorStop(1,'#f4e9fb');
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    const gs=Math.min(176,H-134),cell=gs/2,gx=W/2-gs/2,gy=54;
    // parent gametes slide into the headers
    const drop=ease(clamp01(p/0.3));
    for(let c=0;c<2;c++)chip(gx+cell*c+cell/2,(gy-20)*drop+(1-drop)*8,13,a2[c],a2[c]==='A',drop);
    for(let r=0;r<2;r++)chip((gx-22)*drop+(1-drop)*(gx+gs/2),gy+cell*r+cell/2,13,a1[r],a1[r]==='A',drop);
    let dom=0,rec=0,gAA=0,gAa=0,gaa=0;
    for(let r=0;r<2;r++)for(let c=0;c<2;c++){
      const hasA=(a1[r]==='A'||a2[c]==='A'),hasa=(a1[r]==='a'||a2[c]==='a');
      const combo=hasA&&hasa?'Aa':(hasA?'AA':'aa'),isDom=hasA;
      if(isDom)dom++;else rec++;
      if(combo==='AA')gAA++;else if(combo==='aa')gaa++;else gAa++;
      const x=gx+cell*c,y=gy+cell*r,k=r*2+c;
      const cp=ease(clamp01((p-0.3-k*0.13)/0.24));       // cells pop in one by one
      if(cp<=0)continue;
      ctx.save();
      ctx.translate(x+cell/2,y+cell/2);ctx.scale(0.55+cp*0.45,0.55+cp*0.45);ctx.globalAlpha=cp;
      ctx.fillStyle=isDom?C:'#cbd5e1';ctx.globalAlpha=cp*0.22;ctx.fillRect(-cell/2+2,-cell/2+2,cell-4,cell-4);
      ctx.globalAlpha=cp;
      flower(0,-cell*0.12,cell*0.30,isDom);
      ctx.fillStyle='rgba(25,20,35,0.88)';ctx.font='bold 15px system-ui';ctx.textAlign='center';
      ctx.fillText(combo,0,cell*0.38);
      ctx.restore();
    }
    ctx.globalAlpha=1;
    ctx.strokeStyle='rgba(120,110,130,0.8)';ctx.lineWidth=2;ctx.strokeRect(gx,gy,gs,gs);
    ctx.beginPath();ctx.moveTo(gx+cell,gy);ctx.lineTo(gx+cell,gy+gs);ctx.moveTo(gx,gy+cell);ctx.lineTo(gx+gs,gy+cell);ctx.stroke();
    // ratio bars: phenotype on top, genotype below — numbers only, no wording to translate
    const bw=Math.min(W-60,gs*2.1),bx0=W/2-bw/2,by=gy+gs+24,bh=15;
    const barp=ease(clamp01((p-0.72)/0.28));
    function bar(y,parts){
      let x=bx0;
      parts.forEach(function(seg){
        const w=bw*(seg[0]/4)*barp;
        ctx.fillStyle=seg[1];ctx.fillRect(x,y,w,bh);
        if(seg[0]>0&&w>16){ctx.fillStyle='#fff';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText(seg[0],x+w/2,y+bh-3.5);}
        x+=w;
      });
      ctx.strokeStyle='rgba(120,110,130,0.45)';ctx.lineWidth=1;ctx.strokeRect(bx0,y,bw*barp,bh);
    }
    bar(by,[[dom,C],[rec,'#cbd5e1']]);
    bar(by+bh+7,[[gAA,C],[gAa,'#a78bfa'],[gaa,'#cbd5e1']]);
    pPh.set(dom+' : '+rec+'  (dom:rec)');pGe.set(gAA+' : '+gAa+' : '+gaa+'  (AA:Aa:aa)');
    St.raf=requestAnimationFrame(frame);
  }
  b1.addEventListener('click',function(){g1=(g1+1)%3;b1.textContent=L.p1+': '+GENO[g1];St.t0=performance.now();});
  b2.addEventListener('click',function(){g2=(g2+1)%3;b2.textContent=L.p2+': '+GENO[g2];St.t0=performance.now();});
  frame();
}

function simWaves(container,color,lvl){
  const W=getSimWidth(container),H=260;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('waves',lvl);
  const pType=pill(L.type); const pAmp=pill(L.amp);
  pRow.appendChild(pType.el); pRow.appendChild(pAmp.el);
  const rF=mkRange(ctrl,'Frequency 2',0.5,3,1,0.05,color);
  const rP=mkRange(ctrl,'Phase Shift',0,6.28,0,0.05,color);

  let t=0;
  const S=SIMS.waves={raf:null};

  function frame(){
    const safe=(typeof color==='string'&&color[0]==='#')?color:'#7c3aed';
    // dark background
    const bg=ctx.createLinearGradient(0,0,0,H);
    bg.addColorStop(0,'#0c1322'); bg.addColorStop(1,'#070b14');
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);
    const cy=H/2, A=Math.min(H/2-10,52);
    const f2=rF.val, ph=rP.val;

    // centre line
    ctx.beginPath();ctx.moveTo(0,cy);ctx.lineTo(W,cy);
    ctx.strokeStyle='rgba(255,255,255,0.09)';ctx.lineWidth=1;ctx.stroke();

    // source waves (faint, glowing)
    function srcWave(fn,stroke){
      ctx.save();ctx.shadowColor=stroke;ctx.shadowBlur=6;
      ctx.beginPath();
      for(let x=0;x<=W;x++){const xi=x/W*Math.PI*8;const y=cy+fn(xi);x?ctx.lineTo(x,y):ctx.moveTo(x,y);}
      ctx.strokeStyle=stroke;ctx.lineWidth=1.8;ctx.lineJoin='round';ctx.stroke();ctx.restore();
    }
    srcWave(xi=>A*0.85*Math.sin(xi-t),'rgba(56,189,248,0.5)');
    srcWave(xi=>A*0.85*Math.sin(f2*xi-t+ph),'rgba(167,139,250,0.5)');

    // superposition
    let maxA=0; const pts=[];
    for(let x=0;x<=W;x++){
      const xi=x/W*Math.PI*8;
      const sum=A*Math.sin(xi-t)+A*Math.sin(f2*xi-t+ph);
      if(Math.abs(sum)>maxA)maxA=Math.abs(sum);
      pts.push([x,cy+sum]);
    }
    // soft fill to centre line
    const fillG=ctx.createLinearGradient(0,0,0,H);
    fillG.addColorStop(0,'rgba(255,255,255,0.10)');fillG.addColorStop(0.5,'rgba(255,255,255,0.015)');fillG.addColorStop(1,'rgba(255,255,255,0.10)');
    ctx.beginPath();ctx.moveTo(0,cy);for(const p of pts)ctx.lineTo(p[0],p[1]);ctx.lineTo(W,cy);ctx.closePath();
    ctx.fillStyle=fillG;ctx.fill();
    // bold glowing line
    ctx.save();ctx.shadowColor=safe;ctx.shadowBlur=14;
    ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));
    ctx.strokeStyle=safe;ctx.lineWidth=3.2;ctx.lineJoin='round';ctx.stroke();ctx.restore();

    pType.set(maxA>A*1.6?'Constructive ✓':maxA<A*0.4?'Destructive ✗':'Partial ~');
    pAmp.set((maxA/A).toFixed(2)+'×');
    t+=0.04; S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simThermo(container,color,lvl){
  const safe=(typeof color==='string'&&color[0]==='#')?color:'#ff6b35';
  const W=getSimWidth(container),H=312;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('thermo',lvl);
  const pHits=pill(L.hits); const pAvg=pill(L.speed); const pPres=pill(L.press);
  pRow.appendChild(pHits.el); pRow.appendChild(pAvg.el); pRow.appendChild(pPres.el);
  const rT=mkRange(ctrl,L.temp,50,1200,300,10,safe);
  const rN=mkRange(ctrl,L.num,5,90,30,5,safe);

  // rounded-rect path helper (begins a fresh path)
  function rr(x,y,w,h,rad){
    const k=Math.min(rad,w/2,h/2);
    ctx.beginPath();
    ctx.moveTo(x+k,y);
    ctx.arcTo(x+w,y,x+w,y+h,k);
    ctx.arcTo(x+w,y+h,x,y+h,k);
    ctx.arcTo(x,y+h,x,y,k);
    ctx.arcTo(x,y,x+w,y,k);
    ctx.closePath();
  }
  // geometry: gas box (top-left) + thermometer (top-right) + speed histogram (bottom)
  const pad=14, thermoW=50, r=6, gap=14;
  const bx=pad, by=pad, bw=W-pad*2-thermoW, bh=186;
  const hx=pad, hy=by+bh+gap, hw=W-pad*2, hh=H-hy-pad;

  const NB=20, vMax=11;                              // histogram bins & display-speed range
  let binsT=new Array(NB).fill(0), binsS=new Array(NB).fill(0);

  function speedColor(spd){
    const t=Math.max(0,Math.min(1,spd/8));           // 0 slow → 1 fast
    return `hsl(${212-t*212},88%,${56+t*8}%)`;        // blue → cyan → yellow → red
  }

  let particles=[], sparks=[], wallHits=0, wallImpulse=0, frames=0;
  function initP(){
    particles=[];
    const n=rN.val;
    for(let i=0;i<n;i++){
      const x=bx+r+Math.random()*(bw-2*r), y=by+r+Math.random()*(bh-2*r);
      particles.push({x,y,px:x,py:y,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3});
    }
  }
  rN.inp.addEventListener('input',initP);
  initP();

  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d1424'); bg.addColorStop(1,'#070b13');
  function spark(x,y){ sparks.push({x,y,life:9,max:9}); }

  function drawThermo(){
    const tubeW=13, tubeTop=by+16, tubeBot=by+bh-26, bulbR=13;
    const cx=W-pad-thermoW/2, tx=cx-tubeW/2;
    ctx.fillStyle='rgba(255,255,255,0.09)';
    rr(tx,tubeTop,tubeW,tubeBot-tubeTop,tubeW/2); ctx.fill();
    ctx.beginPath();ctx.arc(cx,tubeBot+bulbR-1,bulbR,0,Math.PI*2);ctx.fill();
    const t=(rT.val-50)/(1200-50);
    const fillTop=tubeBot-(tubeBot-tubeTop)*t;
    const tcol=`hsl(${212-t*212},88%,57%)`;
    ctx.save();ctx.shadowColor=tcol;ctx.shadowBlur=12;ctx.fillStyle=tcol;
    ctx.beginPath();ctx.arc(cx,tubeBot+bulbR-1,bulbR-3,0,Math.PI*2);ctx.fill();
    rr(tx+3,fillTop,tubeW-6,tubeBot-fillTop,(tubeW-6)/2);ctx.fill();
    ctx.restore();
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='800 11px Nunito,sans-serif';ctx.textAlign='center';
    ctx.fillText(rT.val+' K',cx,tubeTop-5);
  }

  function drawHist(){
    const baseY=hy+hh-15, plotH=hh-24, barW=hw/NB;
    // panel + axis
    ctx.fillStyle='rgba(255,255,255,0.04)'; rr(hx,hy,hw,hh,10); ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.14)'; ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(hx+8,baseY);ctx.lineTo(hx+hw-8,baseY);ctx.stroke();
    // bars (fraction of particles per speed bin)
    const tops=[];
    for(let i=0;i<NB;i++){
      const frac=binsS[i], bh2=Math.min(1,frac/0.30)*plotH;
      const x=hx+8+i*((hw-16)/NB), w=(hw-16)/NB-2;
      const cen=(i+0.5)/NB*vMax, col=speedColor(cen);
      ctx.save();ctx.shadowColor=col;ctx.shadowBlur=8;ctx.fillStyle=col;ctx.globalAlpha=.92;
      rr(x,baseY-bh2,w,bh2,Math.min(3,w/2,bh2/2)); ctx.fill();
      ctx.restore();
      tops.push({x:x+w/2,y:baseY-bh2});
    }
    // distribution envelope
    ctx.strokeStyle='rgba(255,255,255,0.5)';ctx.lineWidth=1.5;ctx.beginPath();
    tops.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();
    // labels
    ctx.fillStyle='rgba(255,255,255,0.45)';ctx.font='800 9.5px Nunito,sans-serif';
    ctx.textAlign='left'; ctx.fillText('SLOW',hx+10,hy+13);
    ctx.textAlign='right'; ctx.fillText('FAST',hx+hw-10,hy+13);
    ctx.textAlign='center'; ctx.fillStyle='rgba(255,255,255,0.6)';
    ctx.fillText('Speed distribution  ·  Maxwell–Boltzmann',hx+hw/2,hy+13);
  }

  const S=SIMS.thermo={raf:null};
  function frame(){
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

    const sc=Math.sqrt(rT.val/300)*2;
    const heat=(rT.val-50)/(1200-50);                // 0 cold → 1 hot

    // ambient heat glow inside the box (blue when cold, orange when hot)
    const gx=bx+bw/2, gy=by+bh/2;
    const glow=ctx.createRadialGradient(gx,gy,0,gx,gy,bw*0.6);
    glow.addColorStop(0,`hsla(${30+(1-heat)*180},90%,55%,${0.05+heat*0.16})`);
    glow.addColorStop(1,'rgba(0,0,0,0)');
    ctx.save(); rr(bx,by,bw,bh,12); ctx.clip();
    ctx.fillStyle=glow; ctx.fillRect(bx,by,bw,bh); ctx.restore();

    // glowing container walls
    ctx.save();
    ctx.shadowColor=safe; ctx.shadowBlur=16;
    ctx.strokeStyle=safe; ctx.lineWidth=2;
    rr(bx,by,bw,bh,12); ctx.stroke();
    ctx.restore();

    // integrate + wall bounce
    for(const p of particles){
      p.px=p.x; p.py=p.y;
      p.x+=p.vx*sc; p.y+=p.vy*sc;
      if(p.x<bx+r){p.vx=Math.abs(p.vx);wallHits++;wallImpulse+=Math.abs(p.vx)*sc;spark(bx+r,p.y);}
      else if(p.x>bx+bw-r){p.vx=-Math.abs(p.vx);wallHits++;wallImpulse+=Math.abs(p.vx)*sc;spark(bx+bw-r,p.y);}
      if(p.y<by+r){p.vy=Math.abs(p.vy);wallHits++;wallImpulse+=Math.abs(p.vy)*sc;spark(p.x,by+r);}
      else if(p.y>by+bh-r){p.vy=-Math.abs(p.vy);wallHits++;wallImpulse+=Math.abs(p.vy)*sc;spark(p.x,by+bh-r);}
    }
    // elastic particle-particle collisions (equal mass)
    const minD=2*r;
    for(let i=0;i<particles.length;i++){
      const a=particles[i];
      for(let j=i+1;j<particles.length;j++){
        const b=particles[j];
        const dx=b.x-a.x, dy=b.y-a.y, d2=dx*dx+dy*dy;
        if(d2<minD*minD && d2>1e-6){
          const d=Math.sqrt(d2), nx=dx/d, ny=dy/d;
          const rel=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;
          if(rel>0){ a.vx-=rel*nx; a.vy-=rel*ny; b.vx+=rel*nx; b.vy+=rel*ny; }
          const ov=(minD-d)/2; a.x-=nx*ov; a.y-=ny*ov; b.x+=nx*ov; b.y+=ny*ov;
        }
      }
    }

    // draw particles + accumulate stats/histogram
    let tv=0; binsT.fill(0);
    ctx.save();
    rr(bx,by,bw,bh,12); ctx.clip(); ctx.lineCap='round';
    for(const p of particles){
      p.x=Math.max(bx+r,Math.min(bx+bw-r,p.x));
      p.y=Math.max(by+r,Math.min(by+bh-r,p.y));
      const spd=Math.sqrt(p.vx*p.vx+p.vy*p.vy)*sc; tv+=spd;
      binsT[Math.max(0,Math.min(NB-1,Math.floor(spd/vMax*NB)))]++;
      const col=speedColor(spd);
      ctx.globalAlpha=.30; ctx.strokeStyle=col; ctx.lineWidth=r*1.05;
      ctx.beginPath();ctx.moveTo(p.px,p.py);ctx.lineTo(p.x,p.y);ctx.stroke();
      ctx.globalAlpha=1;
      ctx.shadowColor=col; ctx.shadowBlur=11;
      ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();
      ctx.shadowBlur=0;
      ctx.beginPath();ctx.arc(p.x-r*0.32,p.y-r*0.32,r*0.34,0,Math.PI*2);
      ctx.fillStyle='rgba(255,255,255,0.55)';ctx.fill();
    }
    for(let i=sparks.length-1;i>=0;i--){
      const s2=sparks[i]; s2.life--;
      if(s2.life<=0){sparks.splice(i,1);continue;}
      const al=s2.life/s2.max;
      ctx.globalAlpha=al*0.9; ctx.strokeStyle='#fff'; ctx.lineWidth=1.4;
      ctx.beginPath();ctx.arc(s2.x,s2.y,(1-al)*9+2,0,Math.PI*2);ctx.stroke();
      ctx.globalAlpha=1;
    }
    ctx.restore();

    // ease histogram toward target fractions
    const n=particles.length||1;
    for(let i=0;i<NB;i++) binsS[i]+=((binsT[i]/n)-binsS[i])*0.12;

    drawThermo();
    drawHist();

    frames++;
    if(frames%30===0){
      pHits.set(wallHits*2);
      pAvg.set((tv/n).toFixed(2)+' u/s');
      const perim=2*(bw+bh);
      pPres.set((wallImpulse/perim*120).toFixed(1)+' kPa');
      wallHits=0; wallImpulse=0;
    }
    S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simParticles(container,color,lvl){
  const W=getSimWidth(container),H=290;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('particles',lvl);
  const pColl=pill(L.count); const pEnergy=pill(L.e);
  pRow.appendChild(pColl.el); pRow.appendChild(pEnergy.el);
  const rE=mkRange(ctrl,L.energy,0.5,14,7,0.5,color);
  const bCollide=mkBtn('💥 '+L.collide,true,color);
  ctrl.appendChild(bCollide);
  const particles=[];
  let collisions=0; let t=0;
  const QUARKS=[{n:'u',c:'#ef4444'},{n:'d',c:'#3b82f6'},{n:'s',c:'#10b981'},
                {n:'g',c:'#f59e0b'},{n:'e⁻',c:'#8b5cf6'},{n:'γ',c:'#fbbf24'},
                {n:'ν',c:'rgba(200,200,255,0.8)'},{n:'H',c:'#ec4899'}];
  function spawnDecay(cx,cy,energy){
    const n=4+Math.floor(energy/2);
    for(let i=0;i<n;i++){
      const a=Math.random()*Math.PI*2;
      const spd=2+Math.random()*4*(energy/7);
      const q=QUARKS[Math.floor(Math.random()*QUARKS.length)];
      particles.push({x:cx,y:cy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,
        r:q.n==='H'?8:4+Math.random()*3,col:q.c,sym:q.n,life:80+Math.random()*60,age:0});
    }
    collisions++;
  }
  // initial particles
  function init(){
    particles.length=0;
    for(let i=0;i<30;i++){
      const q=QUARKS[Math.floor(Math.random()*5)];
      particles.push({x:Math.random()*W,y:Math.random()*H,
        vx:(Math.random()-.5)*1.5,vy:(Math.random()-.5)*1.5,
        r:4,col:q.c,sym:q.n,life:999,age:0});
    }
  }
  bCollide.addEventListener('click',()=>{
    spawnDecay(W/2,H/2,rE.val);
    // two beams
    particles.push({x:0,y:H/2,vx:18,vy:0,r:6,col:'rgba(99,102,241,0.9)',sym:'p',life:30,age:0});
    particles.push({x:W,y:H/2,vx:-18,vy:0,r:6,col:'rgba(239,68,68,0.9)',sym:'p̄',life:30,age:0});
  });
  init();
  const S=SIMS.particles={raf:null};
  function frame(){
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#020617';ctx.fillRect(0,0,W,H);
    // detector rings
    const cx=W/2,cy=H/2;
    [60,100,140].forEach((r,i)=>{
      ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);
      ctx.strokeStyle=`rgba(30,58,138,${0.2+i*.1})`;ctx.lineWidth=8;ctx.stroke();
    });
    t++;
    // update & draw particles
    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i];
      p.x+=p.vx; p.y+=p.vy;
      p.vx*=0.99; p.vy*=0.99;
      p.age++;
      if(p.age>p.life||p.x<-20||p.x>W+20||p.y<-20||p.y>H+20){particles.splice(i,1);continue;}
      const alpha=Math.min(1,(p.life-p.age)/20);
      // trail
      ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-p.vx*4,p.y-p.vy*4);
      ctx.strokeStyle=p.col.replace(')',`,${alpha*.5})`).replace('rgb','rgba');
      ctx.lineWidth=1.5;ctx.stroke();
      ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fillStyle=p.col;ctx.globalAlpha=alpha;ctx.fill();ctx.globalAlpha=1;
      ctx.fillStyle='rgba(255,255,255,0.9)';ctx.font=`bold ${p.r+1}px Nunito,sans-serif`;
      ctx.textAlign='center';ctx.textBaseline='middle';ctx.globalAlpha=alpha;
      ctx.fillText(p.sym,p.x,p.y);ctx.globalAlpha=1;
    }
    // auto random decay
    if(t%120===0) spawnDecay(cx+(Math.random()-.5)*40,cy+(Math.random()-.5)*40,rE.val*.3);
    pColl.set(collisions);pEnergy.set(rE.val+' TeV');
    S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simGalton(container,color,lvl){
  const W=getSimWidth(container),H=300;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('prob',lvl);
  const pTot=pill(L.total); const pMean=pill(L.mean);
  pRow.appendChild(pTot.el); pRow.appendChild(pMean.el);

  const bDrop=mkBtn('▶ '+L.drop,true,color);
  const bReset=mkBtn('↺ '+L.reset);
  const rRows=mkRange(ctrl,L.rows,4,10,7,1,color);
  ctrl.prepend(bReset); ctrl.prepend(bDrop);

  let numRows=7, bins, balls=[], total=0, dropping=false, dropInt;
  function reset(){bins=new Array(numRows+1).fill(0);balls=[];total=0;pTot.set('0');pMean.set('-');}
  reset();

  rRows.inp.addEventListener('input',()=>{numRows=rRows.val;reset();});
  bDrop.addEventListener('click',()=>{
    dropping=!dropping;
    bDrop.textContent=dropping?'⏸ Stop':'▶ '+L.drop;
    if(dropping)dropInt=setInterval(()=>{
      balls.push({x:W/2,y:6,row:0,col:0,vy:0,hue:40+Math.random()*18});
    },120);
    else clearInterval(dropInt);
  });
  bReset.addEventListener('click',()=>{
    dropping=false;clearInterval(dropInt);bDrop.textContent='▶ '+L.drop;reset();
  });

  function pp(r,c){
    const sp=Math.min(24,(W-60)/(numRows+1));
    const sy=(H-90)/(numRows+2);
    return{x:W/2+(c-r/2)*sp, y:26+r*sy};
  }

  const S=SIMS.prob={raf:null};
  function frame(){
    // dark background
    const bg=ctx.createLinearGradient(0,0,0,H);
    bg.addColorStop(0,'#0e1322'); bg.addColorStop(1,'#080b14');
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

    // glowing pegs
    for(let r=0;r<=numRows;r++) for(let c=0;c<=r;c++){
      const p=pp(r,c);
      ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);
      ctx.fillStyle='rgba(150,180,230,0.55)';ctx.fill();
    }

    // bins
    const maxB=Math.max(...bins,1);
    const lastY=pp(numRows,0).y+14;
    const maxBH=H-lastY-8;
    const bw=Math.min(22,(W-60)/(numRows+1));
    for(let i=0;i<=numRows;i++){
      const p=pp(numRows,i), bx2=p.x-bw/2;
      const g=Math.exp(-0.5*Math.pow((i-numRows/2)/(Math.sqrt(numRows)/2),2));
      // expected (ghost) bar
      ctx.fillStyle='rgba(255,255,255,0.05)'; ctx.fillRect(bx2,H-8-g*maxBH,bw-2,g*maxBH);
      // data bar with gradient + glow
      if(bins[i]>0){
        const bh=(bins[i]/maxB)*maxBH, hue=190+i*120/numRows;
        const grad=ctx.createLinearGradient(0,H-8-bh,0,H-8);
        grad.addColorStop(0,`hsl(${hue},92%,64%)`); grad.addColorStop(1,`hsl(${hue},92%,46%)`);
        ctx.save();ctx.shadowColor=`hsl(${hue},92%,55%)`;ctx.shadowBlur=10;
        ctx.fillStyle=grad; ctx.fillRect(bx2,H-8-bh,bw-2,bh); ctx.restore();
      }
    }
    // theoretical Gaussian curve overlay
    ctx.strokeStyle='rgba(255,255,255,0.5)';ctx.setLineDash([4,4]);ctx.lineWidth=1.5;ctx.beginPath();
    for(let i=0;i<=numRows;i++){const p=pp(numRows,i);const g=Math.exp(-0.5*Math.pow((i-numRows/2)/(Math.sqrt(numRows)/2),2));const y=H-8-g*maxBH;i?ctx.lineTo(p.x,y):ctx.moveTo(p.x,y);}
    ctx.stroke();ctx.setLineDash([]);

    // animate balls (glowing)
    const alive=[];
    for(const b of balls){
      b.vy+=0.65; b.y+=b.vy;
      if(b.row<=numRows){
        const pin=pp(b.row,b.col);
        if(b.y>=pin.y){b.vy=2.5;b.col+=(Math.random()<.5?1:0);b.row++;b.x=pp(b.row,b.col).x+(Math.random()-.5)*3;}
      }
      if(b.row>numRows&&b.y>H-10){
        const cc=Math.max(0,Math.min(numRows,b.col));   // keep bin index in range
        bins[cc]++; total++;
        pTot.set(total);
        pMean.set((bins.reduce((s,v,i)=>s+v*i,0)/total).toFixed(2));
      } else {
        const col=`hsl(${b.hue},92%,60%)`;
        ctx.save();ctx.shadowColor=col;ctx.shadowBlur=10;
        ctx.beginPath();ctx.arc(b.x,b.y,5,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();ctx.restore();
        ctx.beginPath();ctx.arc(b.x-1.6,b.y-1.6,1.8,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,0.65)';ctx.fill();
        alive.push(b);
      }
    }
    balls=alive;
    S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simFractal(container,color,lvl){
  const W=getSimWidth(container),H=300;
  const {canvas,ctx,dpr}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('fractal',lvl);
  const pZoom=pill(L.zoom); pRow.appendChild(pZoom.el);
  let maxIter=lvl==='junior'?50:lvl==='student'?90:160;
  const rI=mkRange(ctrl,L.detail,20,240,maxIter,5,color);
  const bR=mkBtn('↺ '+L.reset);
  ctrl.appendChild(bR);

  let cx=-0.5,cy=0,zoom=Math.min(W,H)*0.44, dirty=true;

  rI.inp.addEventListener('input',()=>{maxIter=rI.val;dirty=true;});
  bR.addEventListener('click',()=>{cx=-0.5;cy=0;zoom=Math.min(W,H)*0.44;pZoom.set('1×');dirty=true;});

  canvas.style.cursor='crosshair';
  canvas.addEventListener('click',e=>{
    const rect=canvas.getBoundingClientRect();
    const sx=canvas.width/(rect.width*dpr), sy=canvas.height/(rect.height*dpr);
    const mx=(e.clientX-rect.left)*dpr*sx/dpr;
    const my=(e.clientY-rect.top)*dpr*sy/dpr;
    cx+=(mx-W/2)/zoom; cy+=(my-H/2)/zoom;
    zoom*=2.2;
    pZoom.set((zoom/(Math.min(W,H)*0.44)).toFixed(1)+'×');
    dirty=true;
  });

  // 256-entry "stellar" palette (deep blue → cyan → white → gold → red), built once
  const LUT=(()=>{
    const stops=[[0,[10,12,38]],[0.14,[34,58,168]],[0.34,[40,184,222]],
                 [0.52,[224,250,238]],[0.68,[250,202,92]],[0.85,[222,92,42]],[1,[60,16,26]]];
    const lut=new Uint8ClampedArray(256*3);
    for(let i=0;i<256;i++){
      const t=i/255; let a=stops[0],b=stops[stops.length-1];
      for(let s=0;s<stops.length-1;s++){ if(t>=stops[s][0]&&t<=stops[s+1][0]){a=stops[s];b=stops[s+1];break;} }
      const f=(t-a[0])/((b[0]-a[0])||1);
      lut[i*3]=a[1][0]+(b[1][0]-a[1][0])*f;
      lut[i*3+1]=a[1][1]+(b[1][1]-a[1][1])*f;
      lut[i*3+2]=a[1][2]+(b[1][2]-a[1][2])*f;
    }
    return lut;
  })();
  const LOG2=Math.LN2;

  function drawM(){
    // use the canvas's true integer device dimensions (dpr may be fractional, e.g. 1.5)
    const RW=canvas.width, RH=canvas.height;
    const sx=W/RW, sy=H/RH;
    const id=ctx.createImageData(RW,RH);
    const d=id.data;
    for(let py=0;py<RH;py++){
      for(let px=0;px<RW;px++){
        const cr=(px*sx-W/2)/zoom+cx, ci=(py*sy-H/2)/zoom+cy;
        let zr=0,zi=0,it=0,m=0;
        while(it<maxIter){
          const zr2=zr*zr, zi2=zi*zi;
          if(zr2+zi2>64){m=zr2+zi2;break;}
          zi=2*zr*zi+ci; zr=zr2-zi2+cr; it++;
        }
        const idx=(py*RW+px)*4; d[idx+3]=255;
        if(it>=maxIter){ d[idx]=8; d[idx+1]=9; d[idx+2]=24; }   // interior
        else{
          // smooth (continuous) iteration count → no banding
          const nu=Math.log(Math.log(m)/2/LOG2)/LOG2;
          let t=(it+1-nu)/maxIter; t=t<0?0:t>1?1:t;
          const li=(Math.pow(t,0.55)*255)|0, l=li*3;        // boost boundary detail
          d[idx]=LUT[l]; d[idx+1]=LUT[l+1]; d[idx+2]=LUT[l+2];
        }
      }
    }
    ctx.putImageData(id,0,0);
    // vignette for depth
    const vg=ctx.createRadialGradient(W/2,H/2,H*0.22,W/2,H/2,W*0.62);
    vg.addColorStop(0,'rgba(0,0,0,0)'); vg.addColorStop(1,'rgba(0,0,0,0.42)');
    ctx.fillStyle=vg; ctx.fillRect(0,0,W,H);
    // hint
    ctx.font='800 12px Nunito,sans-serif'; ctx.textAlign='left';
    ctx.fillStyle='rgba(255,255,255,0.6)';
    ctx.fillText('🔍 Click anywhere to zoom in',12,H-12);
    dirty=false;
  }

  const S=SIMS.fractal={raf:null};
  function frame(){if(dirty)drawM();S.raf=requestAnimationFrame(frame);}
  frame();
}

function simCalculus(container,color,lvl){
  const W=getSimWidth(container),H=280;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('calculus',lvl);
  const pDeriv=pill(L.deriv); const pInteg=pill(L.integ);
  pRow.appendChild(pDeriv.el); pRow.appendChild(pInteg.el);
  const rX=mkRange(ctrl,L.x,-3,3,0,0.1,color);
  const rN=mkRange(ctrl,L.rects,2,40,8,1,color);
  const S=SIMS.calculus={raf:null};
  const PAD=40, PW=W-PAD*2, PH=H-PAD*2;
  function f(x){return Math.sin(x)+0.4*x;}
  function df(x){return Math.cos(x)+0.4;}
  function toC(x,y){return{px:PAD+((x+4)/8)*PW, py:PAD+((2-y)/4)*PH};}
  function frame(){
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#f8fafc';ctx.fillRect(0,0,W,H);
    // axes
    const o=toC(0,0);
    ctx.strokeStyle='#94a3b8';ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(PAD,o.py);ctx.lineTo(W-PAD,o.py);ctx.stroke();
    ctx.beginPath();ctx.moveTo(o.px,PAD);ctx.lineTo(o.px,H-PAD);ctx.stroke();
    // axis labels
    ctx.fillStyle='#64748b';ctx.font='11px Nunito,sans-serif';ctx.textAlign='center';
    for(let xi=-3;xi<=3;xi++){const p=toC(xi,0);ctx.fillText(xi,p.px,p.py+14);}
    // Riemann rectangles
    // Integrate from -3 up to the x slider, not over the whole fixed span:
    // f is odd on [-3,3] and the midpoint rule is exact there by symmetry, so
    // the old version printed 0.000 for every rectangle count and the slider
    // appeared broken. Running to x also exposes the fundamental theorem.
    const n=rN.val; const a=-3,b=rX.val, dx=(b-a)/n;
    let area=0;
    for(let i=0;i<n;i++){
      const xi=a+i*dx; const yi=f(xi+dx/2); area+=yi*dx;
      const p1=toC(xi,Math.max(0,yi)), p2=toC(xi+dx,0);
      const p1b=toC(xi,Math.min(0,yi));
      const ph=Math.abs(toC(xi,yi).py-o.py);
      ctx.fillStyle=yi>=0?'rgba(99,102,241,0.2)':'rgba(239,68,68,0.15)';
      ctx.fillRect(Math.min(toC(xi,0).px,toC(xi+dx,0).px), Math.min(toC(xi,yi).py,o.py), Math.abs(toC(xi+dx,0).px-toC(xi,0).px), ph);
      ctx.strokeStyle=yi>=0?'rgba(99,102,241,0.5)':'rgba(239,68,68,0.4)';ctx.lineWidth=0.5;
      ctx.strokeRect(Math.min(toC(xi,0).px,toC(xi+dx,0).px), Math.min(toC(xi,yi).py,o.py), Math.abs(toC(xi+dx,0).px-toC(xi,0).px), ph);
    }
    // function curve
    ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=2.5;
    for(let xi=-4;xi<=4;xi+=0.05){const p=toC(xi,f(xi));xi===-4?ctx.moveTo(p.px,p.py):ctx.lineTo(p.px,p.py);}
    ctx.stroke();
    // tangent line at x
    const xv=rX.val, yv=f(xv), slope=df(xv);
    const p0=toC(xv,yv);
    ctx.beginPath();ctx.strokeStyle='#f59e0b';ctx.lineWidth=2;ctx.setLineDash([6,3]);
    const x1=xv-1.5,x2=xv+1.5;
    const p1=toC(x1,yv+slope*(x1-xv)), p2=toC(x2,yv+slope*(x2-xv));
    ctx.moveTo(p1.px,p1.py);ctx.lineTo(p2.px,p2.py);ctx.stroke();ctx.setLineDash([]);
    // point
    ctx.beginPath();ctx.arc(p0.px,p0.py,6,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();
    // labels
    ctx.fillStyle=color;ctx.font='bold 12px Nunito,sans-serif';ctx.textAlign='left';
    ctx.fillText('f(x) = sin(x) + 0.4x',PAD+4,PAD+16);
    ctx.fillStyle='#f59e0b';ctx.fillText('tangent at x='+xv.toFixed(1),PAD+4,PAD+30);
    pDeriv.set(slope.toFixed(3));pInteg.set(area.toFixed(3));
    S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simGraphs(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('graphs', lvl);
  const pInfected = pill(L.reached); const pSteps = pill(L.steps); const pClustr = pill(L.hubcount);
  pRow.appendChild(pInfected.el); pRow.appendChild(pSteps.el); pRow.appendChild(pClustr.el);

  const rNodes = mkRange(ctrl, L.nodes, 10, 40, 22, 1, color);
  const rHubs  = mkRange(ctrl, L.hubs, 1, 6, 3, 1, color);
  const bSpread = mkBtn('▶ ' + L.spread, true, color);
  const bReset  = mkBtn('↺ ' + L.reset);
  ctrl.appendChild(bSpread); ctrl.appendChild(bReset);

  let nodes = [], edges = [], spreading = false, step = 0, timer = null;

  function buildGraph() {
    spreading = false; step = 0;
    if (timer) { clearInterval(timer); timer = null; }
    nodes = []; edges = [];
    const n = rNodes.val;
    const margin = 36;
    for (let i = 0; i < n; i++) {
      nodes.push({
        x: margin + Math.random() * (W - margin * 2),
        y: margin + Math.random() * (H - margin * 2),
        state: 'S', // S=susceptible I=infected R=recovered
        deg: 0, isHub: false
      });
    }
    // Barabási-Albert preferential attachment
    const hubK = rHubs.val;
    const edgeSet = new Set();
    function addEdge(a, b) {
      if (a === b) return;
      const key = Math.min(a,b) + '_' + Math.max(a,b);
      if (!edgeSet.has(key)) { edgeSet.add(key); edges.push([a, b]); nodes[a].deg++; nodes[b].deg++; }
    }
    // seed with small clique
    for (let i = 0; i < Math.min(4, n); i++)
      for (let j = i+1; j < Math.min(4, n); j++) addEdge(i, j);
    // attach new nodes preferentially
    for (let i = 4; i < n; i++) {
      const totalDeg = nodes.slice(0, i).reduce((s, nd) => s + nd.deg + 1, 0);
      const targets = new Set();
      let attempts = 0;
      while (targets.size < Math.min(hubK, i) && attempts < 200) {
        let r = Math.random() * totalDeg, cum = 0;
        for (let j = 0; j < i; j++) {
          cum += nodes[j].deg + 1;
          if (r <= cum) { targets.add(j); break; }
        }
        attempts++;
      }
      targets.forEach(j => addEdge(i, j));
    }
    // mark hubs (top 15% by degree)
    const sorted = [...nodes].sort((a, b) => b.deg - a.deg);
    const hubThresh = sorted[Math.floor(n * 0.15)].deg;
    nodes.forEach(nd => { nd.isHub = nd.deg >= hubThresh && hubThresh > 0; });
    pInfected.set('0 / ' + n); pSteps.set(0); pClustr.set(nodes.filter(nd => nd.isHub).length);
  }

  function startSpread() {
    if (spreading) return;
    nodes.forEach(nd => nd.state = 'S');
    // infect a random hub if possible, else random node
    const hubs = nodes.filter(nd => nd.isHub);
    const seed = hubs.length ? hubs[Math.floor(Math.random() * hubs.length)] : nodes[Math.floor(Math.random() * nodes.length)];
    seed.state = 'I';
    step = 0; spreading = true;
    timer = setInterval(() => {
      step++;
      // BFS-style spread: each infected node tries to infect neighbours
      const newlyInfected = [];
      edges.forEach(([a, b]) => {
        if (nodes[a].state === 'I' && nodes[b].state === 'S' && Math.random() < 0.55) newlyInfected.push(b);
        if (nodes[b].state === 'I' && nodes[a].state === 'S' && Math.random() < 0.55) newlyInfected.push(a);
      });
      newlyInfected.forEach(i => nodes[i].state = 'I');
      // some infected → recovered
      nodes.forEach(nd => { if (nd.state === 'I' && Math.random() < 0.18) nd.state = 'R'; });
      const inf = nodes.filter(nd => nd.state === 'I').length;
      const rec = nodes.filter(nd => nd.state === 'R').length;
      pInfected.set((inf + rec) + ' / ' + nodes.length);
      pSteps.set(step);
      if (inf === 0) { spreading = false; clearInterval(timer); timer = null; }
    }, 320);
  }

  bSpread.addEventListener('click', startSpread);
  bReset.addEventListener('click', buildGraph);
  rNodes.inp.addEventListener('input', buildGraph);
  rHubs.inp.addEventListener('input', buildGraph);
  buildGraph();

  // ── physics layout (force-directed) ──────────────────────────────
  const vx = [], vy = [];
  nodes.forEach(() => { vx.push(0); vy.push(0); });

  const S = SIMS.graphs = { raf: null };

  function frame() {
    // force-directed layout (runs every frame for smooth settling)
    const k = 60, rep = 2800, damp = 0.82;
    nodes.forEach((a, i) => {
      let fx = 0, fy = 0;
      // repulsion
      nodes.forEach((b, j) => {
        if (i === j) return;
        const dx = a.x - b.x, dy = a.y - b.y;
        const d = Math.sqrt(dx * dx + dy * dy) + 0.1;
        const f = rep / (d * d);
        fx += (dx / d) * f; fy += (dy / d) * f;
      });
      // attraction along edges
      edges.forEach(([p, q]) => {
        const other = p === i ? q : q === i ? p : -1;
        if (other < 0) return;
        const dx = nodes[other].x - a.x, dy = nodes[other].y - a.y;
        const d = Math.sqrt(dx * dx + dy * dy) + 0.1;
        const f = (d - k) * 0.03;
        fx += (dx / d) * f; fy += (dy / d) * f;
      });
      // centre pull
      fx += (W / 2 - a.x) * 0.004; fy += (H / 2 - a.y) * 0.004;
      vx[i] = (vx[i] + fx) * damp; vy[i] = (vy[i] + fy) * damp;
    });
    nodes.forEach((nd, i) => {
      nd.x = Math.max(24, Math.min(W - 24, nd.x + vx[i]));
      nd.y = Math.max(24, Math.min(H - 24, nd.y + vy[i]));
    });

    // ── draw ─────────────────────────────────────────────────────
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);

    // edges
    edges.forEach(([a, b]) => {
      const na = nodes[a], nb = nodes[b];
      const active = na.state !== 'S' || nb.state !== 'S';
      ctx.beginPath(); ctx.moveTo(na.x, na.y); ctx.lineTo(nb.x, nb.y);
      ctx.strokeStyle = active ? 'rgba(251,191,36,0.35)' : 'rgba(148,163,184,0.18)';
      ctx.lineWidth = active ? 1.8 : 1;
      ctx.stroke();
    });

    // nodes
    nodes.forEach(nd => {
      const r = nd.isHub ? 13 : 8;
      // glow for hubs
      if (nd.isHub) {
        ctx.beginPath(); ctx.arc(nd.x, nd.y, r + 6, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(8,145,178,0.18)'; ctx.fill();
      }
      const fill =
        nd.state === 'I' ? '#f59e0b' :
        nd.state === 'R' ? '#10b981' :
        nd.isHub ? color : '#475569';
      ctx.beginPath(); ctx.arc(nd.x, nd.y, r, 0, Math.PI * 2);
      ctx.fillStyle = fill; ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.25)'; ctx.lineWidth = 1.2; ctx.stroke();
      // degree label on hubs
      if (nd.isHub) {
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 9px Nunito,sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(nd.deg, nd.x, nd.y);
      }
    });

    // legend
    const leg = [['#f59e0b','Infected'],['#10b981','Recovered'],['#475569','Susceptible'],[color,'Hub']];
    leg.forEach(([c, lbl], i) => {
      ctx.beginPath(); ctx.arc(14, 14 + i * 18, 5, 0, Math.PI * 2);
      ctx.fillStyle = c; ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.65)'; ctx.font = '10px Nunito,sans-serif';
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      ctx.fillText(lbl, 24, 14 + i * 18);
    });

    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simLife(container,color,lvl){
  const W=getSimWidth(container),H=290;
  const {canvas,ctx,dpr}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('life',lvl);
  const pGen=pill(L.gen); const pAlive=pill(L.alive);
  pRow.appendChild(pGen.el); pRow.appendChild(pAlive.el);

  const bTog=mkBtn('⏸ '+L.pause);bTog.style.cssText=`border-color:${color};color:${color}`;
  const bClear=mkBtn('✕ '+L.clear);
  const bRand=mkBtn('⚡ '+L.random);
  const bGlider=mkBtn('🛸 '+L.glider,true,color);
  [bTog,bClear,bRand,bGlider].forEach(b=>ctrl.appendChild(b));

  const CELL=9;
  const cols=Math.floor(W/CELL), rows=Math.floor(H/CELL);
  let grid=new Uint8Array(cols*rows), next=new Uint8Array(cols*rows);
  let running=true, gen=0;

  const idx=(r,c)=>r*cols+c;
  const N=(r,c)=>{ let n=0; for(let dr=-1;dr<=1;dr++) for(let dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;n+=grid[idx((r+dr+rows)%rows,(c+dc+cols)%cols)];}return n;};

  function randomize(){for(let i=0;i<grid.length;i++)grid[i]=Math.random()<0.28?1:0;gen=0;}
  function clearG(){grid.fill(0);gen=0;}
  function glider(r,c){[[0,1],[1,2],[2,0],[2,1],[2,2]].forEach(([dr,dc])=>{if(r+dr<rows&&c+dc<cols)grid[idx(r+dr,c+dc)]=1;});}
  function step(){
    let alive=0;
    for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
      const n=N(r,c), cur=grid[idx(r,c)];
      next[idx(r,c)]=(cur&&(n===2||n===3))||(!cur&&n===3)?1:0;
      if(next[idx(r,c)])alive++;
    }
    [grid,next]=[next,grid];gen++;
    pGen.set(gen);pAlive.set(alive);
  }

  bTog.addEventListener('click',()=>{running=!running;bTog.textContent=running?'⏸ Pause':'▶ Play';});
  bClear.addEventListener('click',clearG);
  bRand.addEventListener('click',randomize);
  bGlider.addEventListener('click',()=>{clearG();glider(2,2);glider(3,Math.floor(cols/2));glider(Math.floor(rows/2),Math.floor(cols/3));});
  canvas.addEventListener('click',e=>{
    const rect=canvas.getBoundingClientRect();
    const c2=Math.floor((e.clientX-rect.left)/CELL), r2=Math.floor((e.clientY-rect.top)/CELL);
    if(r2>=0&&r2<rows&&c2>=0&&c2<cols) grid[idx(r2,c2)]^=1;
  });
  randomize();

  const S=SIMS.life={raf:null,timer:null};
  function frame(){
    ctx.fillStyle='#f4f9f4';ctx.fillRect(0,0,W,H);
    for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
      if(!grid[idx(r,c)])continue;
      ctx.fillStyle=color+'e0';
      ctx.fillRect(c*CELL+1,r*CELL+1,CELL-2,CELL-2);
    }
    if(running) step();
    S.timer=setTimeout(()=>{S.raf=requestAnimationFrame(frame);},72);
  }
  frame();
}

function simDNA(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('dna', lvl);
  const pPairs = pill(L.pairs); const pErrors = pill(L.errors);
  pRow.appendChild(pPairs.el); pRow.appendChild(pErrors.el);
  const rSpeed = mkRange(ctrl, L.speed, 1, 8, 3, 1, color);
  const bReset = mkBtn('↺ ' + L.reset, true, color);
  ctrl.appendChild(bReset);

  const BASES = ['A','T','C','G'];
  const PAIR  = {A:'T', T:'A', C:'G', G:'C'};
  const BCOL  = {A:'#ef4444', T:'#3b82f6', C:'#10b981', G:'#f59e0b'};
  const NSTRANDS = 28;
  let strand = [], progress = 0, errors = 0, copied = 0;

  function init() {
    strand = [];
    for (let i = 0; i < NSTRANDS; i++) {
      const b = BASES[Math.floor(Math.random() * 4)];
      strand.push({ base: b, complement: PAIR[b], copied: false, error: false });
    }
    progress = 0; errors = 0; copied = 0;
  }
  bReset.addEventListener('click', init);
  init();

  let t = 0;
  const S = SIMS.dna = { raf: null };

  function frame() {
    t++;
    // advance replication fork
    const spd = rSpeed.val;
    if (t % Math.max(1, Math.round(8 / spd)) === 0 && progress < NSTRANDS) {
      // rare mutation
      if (Math.random() < 0.04) { strand[progress].error = true; errors++; }
      strand[progress].copied = true;
      progress++;
      copied++;
    }

    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);

    const cx = W / 2;
    const yStart = 24, yEnd = H - 24;
    const slotH = (yEnd - yStart) / NSTRANDS;
    const helix_amp = 28;
    const fork = progress / NSTRANDS; // 0..1

    for (let i = 0; i < NSTRANDS; i++) {
      const y = yStart + i * slotH + slotH / 2;
      const phase = (i / NSTRANDS) * Math.PI * 4 + t * 0.04;
      const opened = i < progress;
      const spread = opened ? 1 : 0;

      // helix strands
      const xL = cx - helix_amp * Math.cos(phase);
      const xR = cx + helix_amp * Math.cos(phase);

      // separation (unzipping)
      const openAmt = opened ? helix_amp * 1.6 : 0;
      const xL2 = cx - helix_amp * Math.cos(phase) - openAmt;
      const xR2 = cx + helix_amp * Math.cos(phase) + openAmt;

      const bd = strand[i];
      const col = BCOL[bd.base];
      const colC = BCOL[bd.complement];

      if (!opened) {
        // draw rungs (hydrogen bonds)
        ctx.beginPath(); ctx.moveTo(xL, y); ctx.lineTo(xR, y);
        ctx.strokeStyle = 'rgba(255,255,255,0.12)'; ctx.lineWidth = 1; ctx.stroke();
        // base circles
        ctx.beginPath(); ctx.arc(xL, y, 7, 0, Math.PI * 2);
        ctx.fillStyle = col; ctx.fill();
        ctx.beginPath(); ctx.arc(xR, y, 7, 0, Math.PI * 2);
        ctx.fillStyle = colC; ctx.fill();
        // letters
        ctx.fillStyle = '#fff'; ctx.font = 'bold 8px Nunito,sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(bd.base, xL, y);
        ctx.fillText(bd.complement, xR, y);
      } else {
        // opened - draw new complementary bases appearing
        const errCol = '#a855f7';
        // original strands
        ctx.beginPath(); ctx.arc(xL2, y, 7, 0, Math.PI * 2);
        ctx.fillStyle = col; ctx.fill();
        ctx.beginPath(); ctx.arc(xR2, y, 7, 0, Math.PI * 2);
        ctx.fillStyle = colC; ctx.fill();
        // new complementary (copy)
        ctx.beginPath(); ctx.arc(xL2 + 18, y, 6, 0, Math.PI * 2);
        ctx.fillStyle = bd.error ? errCol : colC; ctx.fill();
        ctx.beginPath(); ctx.arc(xR2 - 18, y, 6, 0, Math.PI * 2);
        ctx.fillStyle = bd.error ? errCol : col; ctx.fill();
        // letters
        ctx.fillStyle = '#fff'; ctx.font = 'bold 8px Nunito,sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(bd.base, xL2, y);
        ctx.fillText(bd.complement, xR2, y);
        ctx.fillText(bd.error ? '?' : bd.complement, xL2 + 18, y);
        ctx.fillText(bd.error ? '?' : bd.base, xR2 - 18, y);
        // dashed bond lines
        ctx.setLineDash([3, 3]);
        ctx.beginPath(); ctx.moveTo(xL2, y); ctx.lineTo(xL2 + 14, y);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.lineWidth = 1; ctx.stroke();
        ctx.beginPath(); ctx.moveTo(xR2, y); ctx.lineTo(xR2 - 14, y);
        ctx.stroke(); ctx.setLineDash([]);
      }
    }

    // replication fork indicator
    if (progress < NSTRANDS) {
      const fy = yStart + progress * slotH;
      ctx.beginPath(); ctx.moveTo(cx - 60, fy); ctx.lineTo(cx + 60, fy);
      ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2;
      ctx.setLineDash([4, 4]); ctx.stroke(); ctx.setLineDash([]);
      ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 10px Nunito,sans-serif';
      ctx.textAlign = 'center'; ctx.fillText('← replication fork →', cx, fy - 6);
    }

    // reset when done
    if (progress >= NSTRANDS && t % 140 === 0) init();

    pPairs.set(copied); pErrors.set(errors);
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simEvolution(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('evolution', lvl);
  const pGen = pill(L.gen); const pFit = pill(L.fit); const pDiv = pill(L.div);
  pRow.appendChild(pGen.el); pRow.appendChild(pFit.el); pRow.appendChild(pDiv.el);
  const rSel = mkRange(ctrl, L.sel, 0, 10, 5, 1, color);
  const rMut = mkRange(ctrl, L.mut, 0, 10, 3, 1, color);
  const bReset = mkBtn('↺ ' + L.reset, true, color);
  ctrl.appendChild(bReset);

  // Each individual: hue (trait) + fitness derived from environment optimum
  const N = 60;
  let pop = [], gen = 0, envHue = 120; // environment optimum hue (green = forest)
  let envDrift = 0.3;

  function initPop() {
    pop = [];
    gen = 0;
    for (let i = 0; i < N; i++) {
      pop.push({ hue: Math.random() * 360, x: 20 + Math.random() * (W - 40), y: 50 + Math.random() * (H - 80), vx: (Math.random() - .5) * .8, vy: (Math.random() - .5) * .8 });
    }
  }
  bReset.addEventListener('click', initPop);
  initPop();

  function hueDist(a, b) { const d = Math.abs(a - b) % 360; return Math.min(d, 360 - d); }
  function fitness(ind) { return Math.max(0, 1 - hueDist(ind.hue, envHue) / 180); }

  let frameCount = 0;
  const S = SIMS.evolution = { raf: null };

  function frame() {
    frameCount++;
    ctx.clearRect(0, 0, W, H);

    // environment background gradient
    const envR = Math.round(Math.sin(envHue * Math.PI / 180) * 40 + 30);
    const envG = Math.round(Math.cos((envHue - 120) * Math.PI / 180) * 40 + 60);
    ctx.fillStyle = `hsl(${envHue}, 35%, 14%)`; ctx.fillRect(0, 0, W, H);

    // env label
    ctx.fillStyle = `hsl(${envHue}, 70%, 70%)`;
    ctx.font = 'bold 11px Nunito,sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('Environment optimum:', 10, 18);
    ctx.beginPath(); ctx.arc(210, 13, 7, 0, Math.PI * 2);
    ctx.fillStyle = `hsl(${envHue}, 80%, 55%)`; ctx.fill();

    // slowly drift environment
    envHue = (envHue + envDrift + 360) % 360;
    if (Math.random() < 0.005) envDrift = (Math.random() - .5) * 1.2;

    // generational update every 38 frames
    if (frameCount % 38 === 0) {
      gen++;
      const sel = rSel.val / 10;
      const mut = rMut.val / 10;
      // compute fitnesses
      const fits = pop.map(fitness);
      const totalFit = fits.reduce((a, b) => a + b, 0) || 1;
      // selection: weighted sampling
      const newPop = [];
      for (let i = 0; i < N; i++) {
        let r = Math.random() * totalFit, cum = 0, picked = pop[0];
        for (let j = 0; j < N; j++) {
          cum += fits[j] * sel + (1 - sel) * (totalFit / N);
          if (r <= cum) { picked = pop[j]; break; }
        }
        // mutation
        const newHue = (picked.hue + (Math.random() - .5) * 60 * mut + 360) % 360;
        newPop.push({ hue: newHue, x: 20 + Math.random() * (W - 40), y: 50 + Math.random() * (H - 80), vx: (Math.random() - .5) * .8, vy: (Math.random() - .5) * .8 });
      }
      pop = newPop;
    }

    // move & draw individuals
    let totalFit = 0, hues = [];
    pop.forEach(ind => {
      ind.x += ind.vx; ind.y += ind.vy;
      if (ind.x < 14 || ind.x > W - 14) ind.vx *= -1;
      if (ind.y < 34 || ind.y > H - 14) ind.vy *= -1;
      const f = fitness(ind);
      totalFit += f;
      hues.push(ind.hue);
      const r = 5 + f * 5;
      ctx.beginPath(); ctx.arc(ind.x, ind.y, r, 0, Math.PI * 2);
      ctx.fillStyle = `hsl(${ind.hue}, 80%, ${40 + f * 30}%)`;
      ctx.globalAlpha = 0.5 + f * 0.5;
      ctx.fill(); ctx.globalAlpha = 1;
    });

    // diversity = std dev of hues (circular)
    const meanHue = hues.reduce((a, b) => a + b, 0) / hues.length;
    const diversity = Math.sqrt(hues.reduce((s, h) => s + hueDist(h, meanHue) ** 2, 0) / hues.length);

    pGen.set(gen);
    pFit.set((totalFit / N).toFixed(2));
    pDiv.set(Math.round(diversity) + '°');
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simEcosystem(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('ecosystem', lvl);
  const pPlants = pill(L.plants); const pHerb = pill(L.herb); const pPred = pill(L.preds);
  pRow.appendChild(pPlants.el); pRow.appendChild(pHerb.el); pRow.appendChild(pPred.el);
  const rGrowth = mkRange(ctrl, L.growth, 1, 10, 5, 1, color);
  const rPred = mkRange(ctrl, L.pred, 1, 10, 4, 1, color);
  const bReset = mkBtn('↺ ' + L.reset, true, color);
  ctrl.appendChild(bReset);

  // Agent-based: plants (green), herbivores (orange), predators (red)
  let agents = [], time = 0;

  function initAgents() {
    agents = []; time = 0;
    for (let i = 0; i < 85; i++) agents.push({ type: 'plant', x: Math.random() * W, y: Math.random() * H, energy: 1, age: 0 });
    for (let i = 0; i < 22; i++) agents.push({ type: 'herb',  x: Math.random() * W, y: Math.random() * H, energy: 10, vx: (Math.random()-.5)*1.4, vy: (Math.random()-.5)*1.4, age: 0 });
    for (let i = 0; i < 7;  i++) agents.push({ type: 'pred',  x: Math.random() * W, y: Math.random() * H, energy: 20, vx: (Math.random()-.5)*1.8, vy: (Math.random()-.5)*1.8, age: 0 });
  }
  bReset.addEventListener('click', initAgents);
  initAgents();

  const S = SIMS.ecosystem = { raf: null };

  function frame() {
    time++;
    ctx.clearRect(0, 0, W, H);
    // background
    ctx.fillStyle = '#0a1a0a'; ctx.fillRect(0, 0, W, H);

    const growthR = rGrowth.val / 10;
    const predEff = rPred.val / 10;

    // spawn new plants - rate scales with the growth slider so herbivores can feed
    if (time % 6 === 0) {
      const nPlant = agents.filter(a => a.type === 'plant').length;
      const grow = Math.max(1, Math.round(growthR * 3.5));
      for (let k = 0; k < grow && nPlant + k < 180; k++)
        agents.push({ type: 'plant', x: Math.random() * W, y: Math.random() * H, energy: 1, age: 0 });
    }

    const toRemove = new Set();
    const toAdd = [];

    agents.forEach((a, i) => {
      a.age++;
      if (a.type === 'plant') {
        // draw plant
        const g = Math.min(1, a.age / 60);
        ctx.beginPath(); ctx.arc(a.x, a.y, 3 + g * 2, 0, Math.PI * 2);
        ctx.fillStyle = `hsl(120, ${50 + g * 30}%, ${25 + g * 20}%)`; ctx.fill();
      } else {
        // move
        a.vx += (Math.random() - .5) * .3;
        a.vy += (Math.random() - .5) * .3;
        const maxV = a.type === 'pred' ? 2.2 : 1.6;
        const spd = Math.sqrt(a.vx * a.vx + a.vy * a.vy);
        if (spd > maxV) { a.vx = a.vx / spd * maxV; a.vy = a.vy / spd * maxV; }
        a.x = (a.x + a.vx + W) % W; a.y = (a.y + a.vy + H) % H;
        a.energy -= (a.type === 'pred' ? 0.022 : 0.03);
        if (a.energy <= 0 || a.age > 600) { toRemove.add(i); return; }

        // eat
        if (a.type === 'herb') {
          for (let j = 0; j < agents.length; j++) {
            if (toRemove.has(j)) continue;
            const b = agents[j];
            if (b.type !== 'plant') continue;
            const dx = b.x - a.x, dy = b.y - a.y;
            if (dx * dx + dy * dy < 225) { a.energy += 5; toRemove.add(j); break; }
          }
          if (a.energy > 16 && Math.random() < 0.012) {
            toAdd.push({ type: 'herb', x: a.x + (Math.random()-.5)*10, y: a.y + (Math.random()-.5)*10, energy: 8, vx: (Math.random()-.5)*1.4, vy: (Math.random()-.5)*1.4, age: 0 });
            a.energy -= 6;
          }
        }
        if (a.type === 'pred') {
          for (let j = 0; j < agents.length; j++) {
            if (toRemove.has(j)) continue;
            const b = agents[j];
            if (b.type !== 'herb') continue;
            const dx = b.x - a.x, dy = b.y - a.y;
            if (dx * dx + dy * dy < 160) { a.energy += 11 * predEff; toRemove.add(j); break; }
          }
          if (a.energy > 18 && Math.random() < 0.007) {
            toAdd.push({ type: 'pred', x: a.x + (Math.random()-.5)*10, y: a.y + (Math.random()-.5)*10, energy: 12, vx: (Math.random()-.5)*1.8, vy: (Math.random()-.5)*1.8, age: 0 });
            a.energy -= 8;
          }
        }

        // draw animal
        const r = a.type === 'pred' ? 7 : 5;
        const fc = a.type === 'pred' ? `hsl(0,75%,${40+a.energy}%)` : `hsl(35,80%,${40+a.energy*.8}%)`;
        ctx.beginPath(); ctx.arc(a.x, a.y, r, 0, Math.PI * 2);
        ctx.fillStyle = fc; ctx.fill();
        // energy bar
        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        ctx.fillRect(a.x - r, a.y - r - 4, r * 2, 2);
        ctx.fillStyle = a.type === 'pred' ? '#ef4444' : '#f59e0b';
        ctx.fillRect(a.x - r, a.y - r - 4, r * 2 * Math.min(1, a.energy / 20), 2);
      }
    });

    // rebuild agents array
    const newAgents = agents.filter((_, i) => !toRemove.has(i));
    newAgents.push(...toAdd);
    agents.length = 0; agents.push(...newAgents);

    const nP = agents.filter(a => a.type === 'plant').length;
    const nH = agents.filter(a => a.type === 'herb').length;
    const nPr = agents.filter(a => a.type === 'pred').length;

    pPlants.set(nP); pHerb.set(nH); pPred.set(nPr);

    // rescue effect - immigration from neighbouring habitats keeps the cycle going
    if (nH < 4 && Math.random() < 0.06)
      agents.push({ type: 'herb', x: Math.random()*W, y: Math.random()*H, energy: 10, vx: (Math.random()-.5)*1.4, vy: (Math.random()-.5)*1.4, age: 0 });
    if (nPr < 2 && Math.random() < 0.06)
      agents.push({ type: 'pred', x: Math.random()*W, y: Math.random()*H, energy: 16, vx: (Math.random()-.5)*1.8, vy: (Math.random()-.5)*1.8, age: 0 });

    // trophic collapse warning
    if (nH === 0 || nPr === 0) {
      ctx.fillStyle = 'rgba(239,68,68,0.85)'; ctx.font = 'bold 13px Nunito,sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(nH === 0 ? '⚠️ Herbivores extinct - ecosystem collapse!' : '⚠️ Predators gone - herbivore explosion!', W / 2, H / 2);
    }

    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simPhotosynthesis(container,color,lvl){
  const C=(typeof color==='string'&&color[0]==='#')?color:'#65a30d';
  window.SIMS=window.SIMS||{};
  if(SIMS.photosynthesis&&SIMS.photosynthesis.raf)cancelAnimationFrame(SIMS.photosynthesis.raf);
  const W=getSimWidth(container),H=290;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('photosynthesis',lvl);
  const pRate=pill(L.rate),pLim=pill(L.limit);
  pRow.appendChild(pRate.el);pRow.appendChild(pLim.el);
  const rL=mkRange(ctrl,L.light,0,100,60,1,color);
  const rC=mkRange(ctrl,L.co2,0,100,45,1,color);
  let bubbles=[],timer=0;
  const St=SIMS.photosynthesis={raf:null};
  const groundY=H-16,plantX=W*0.3,tipY=H*0.4;
  function frame(){
    const light=rL.val,co2=rC.val,ls=light/(light+25),cs=co2/(co2+25),rate=Math.min(ls,cs);
    const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#cbeafe');bg.addColorStop(1,'#7fc4e8');
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    const sunA=0.2+light/100*0.8,sx=W-44,sy=38;
    const sg=ctx.createRadialGradient(sx,sy,4,sx,sy,52);
    sg.addColorStop(0,'rgba(255,224,90,'+sunA+')');sg.addColorStop(1,'rgba(255,224,90,0)');
    ctx.fillStyle=sg;ctx.beginPath();ctx.arc(sx,sy,52,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(255,206,50,'+sunA+')';ctx.beginPath();ctx.arc(sx,sy,15,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#7a5230';ctx.fillRect(0,groundY,W,H-groundY);
    ctx.lineCap='round';
    for(let i=-1;i<=1;i++){
      const bx=plantX+i*17;
      ctx.strokeStyle='#2f7d32';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(bx,groundY);
      for(let y=groundY;y>tipY;y-=6){ctx.lineTo(bx+Math.sin((y+i*20)*0.05)*5,y);}
      ctx.stroke();
      ctx.fillStyle='#3fa346';
      for(let k=0;k<3;k++){const ly=groundY-34-k*38;ctx.beginPath();ctx.ellipse(bx+8,ly,9,4,-0.5,0,Math.PI*2);ctx.fill();}
    }
    timer++;
    const spawnEvery=rate>0.02?Math.max(4,Math.round(46*(1-rate))):100000;
    if(timer>=spawnEvery){timer=0;bubbles.push({x:plantX+(Math.random()*2-1)*15,y:tipY,r:2+Math.random()*2.5,w:Math.random()*6.28});}
    for(let i=bubbles.length-1;i>=0;i--){
      const b=bubbles[i];b.y-=1.4;b.x+=Math.sin(b.w+b.y*0.05)*0.4;
      ctx.fillStyle='rgba(255,255,255,0.78)';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();
      if(b.y<6)bubbles.splice(i,1);
    }
    pRate.set(Math.round(rate/0.8*100)+'%');
    pLim.set(Math.abs(ls-cs)<0.05?'Balanced':(ls<cs?'Light':'CO₂'));
    St.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simCell(container,color,lvl){
  const C=(typeof color==='string'&&color[0]==='#')?color:'#0891b2';
  window.SIMS=window.SIMS||{};
  if(SIMS.cell&&SIMS.cell.raf)cancelAnimationFrame(SIMS.cell.raf);
  const W=getSimWidth(container),H=260;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('cell',lvl);
  const pL=pill(L.left),pR=pill(L.right);
  pRow.appendChild(pL.el);pRow.appendChild(pR.el);
  const rS=mkRange(ctrl,L.salt,0,100,60,1,color);
  const bReset=mkBtn(L.reset||'Reset');ctrl.appendChild(bReset);
  let wL=100,wR=100,dots=[];
  bReset.addEventListener('click',function(){wL=100;wR=100;});
  const St=SIMS.cell={raf:null};
  const pad=14,top=20,bot=H-22,midX=W/2,tankW=(W/2)-pad-8,maxLvl=175,span=bot-top;
  function ensureDots(n){while(dots.length<n)dots.push({x:midX+10+Math.random()*(tankW-12),y:top+Math.random()*(bot-top),vx:(Math.random()*2-1)*0.7,vy:(Math.random()*2-1)*0.7});dots.length=n;}
  function frame(){
    const soluteR=rS.val,concL=0,concR=soluteR/Math.max(wR,1);
    const flux=0.5*(concR-concL)-0.03*(wR-wL);
    let d=flux*0.5;
    if(wL-d<30)d=wL-30;if(wR+d>maxLvl)d=maxLvl-wR;if(wL-d>maxLvl)d=wL-maxLvl;if(wR+d<30)d=30-wR;
    wL-=d;wR+=d;
    ctx.clearRect(0,0,W,H);
    const lh=Math.min(span,wL/maxLvl*span),rh=Math.min(span,wR/maxLvl*span);
    ctx.fillStyle=C+'55';ctx.fillRect(pad,bot-lh,tankW,lh);ctx.fillRect(midX+8,bot-rh,tankW,rh);
    const nS=Math.round(soluteR/6);ensureDots(nS);
    ctx.fillStyle='#f97316';const rtop=bot-rh;
    for(let i=0;i<dots.length;i++){
      const dd=dots[i];dd.x+=dd.vx;dd.y+=dd.vy;
      if(dd.x<midX+10||dd.x>midX+6+tankW){dd.vx*=-1;dd.x=Math.max(midX+10,Math.min(midX+6+tankW,dd.x));}
      if(dd.y<rtop+5||dd.y>bot-5){dd.vy*=-1;dd.y=Math.max(rtop+5,Math.min(bot-5,dd.y));}
      ctx.beginPath();ctx.arc(dd.x,dd.y,3.5,0,Math.PI*2);ctx.fill();
    }
    ctx.strokeStyle='rgba(90,90,90,0.8)';ctx.lineWidth=3;ctx.setLineDash([8,7]);
    ctx.beginPath();ctx.moveTo(midX,top-4);ctx.lineTo(midX,bot);ctx.stroke();ctx.setLineDash([]);
    ctx.strokeStyle='rgba(90,90,90,0.5)';ctx.lineWidth=2;
    ctx.strokeRect(pad,top,tankW,bot-top);ctx.strokeRect(midX+8,top,tankW,bot-top);
    if(Math.abs(flux)>0.02){
      const dir=flux>0?1:-1,ay=top+16,alpha=Math.min(1,Math.abs(flux)*4),a2=midX+22*dir;
      ctx.strokeStyle='rgba(37,99,235,'+alpha+')';ctx.fillStyle='rgba(37,99,235,'+alpha+')';ctx.lineWidth=3;
      ctx.beginPath();ctx.moveTo(midX-22*dir,ay);ctx.lineTo(a2,ay);ctx.stroke();
      ctx.beginPath();ctx.moveTo(a2,ay);ctx.lineTo(a2-9*dir,ay-5);ctx.lineTo(a2-9*dir,ay+5);ctx.closePath();ctx.fill();
    }
    ctx.fillStyle='rgba(40,40,40,0.7)';ctx.font='11px system-ui';ctx.textAlign='center';
    ctx.fillText('pure water',pad+tankW/2,bot+15);ctx.fillText('+ solute',midX+8+tankW/2,bot+15);
    ctx.textAlign='left';
    pL.set(Math.round(wL));pR.set(Math.round(wR));
    St.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simMitosis(container,color,lvl){
  const C=(typeof color==='string'&&color[0]==='#')?color:'#9333ea';
  window.SIMS=window.SIMS||{};
  if(SIMS.mitosis&&SIMS.mitosis.raf)cancelAnimationFrame(SIMS.mitosis.raf);
  const W=getSimWidth(container),H=410;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('mitosis',lvl);
  const pPhase=pill(L.phase),pCells=pill(L.cells);
  pRow.appendChild(pPhase.el);pRow.appendChild(pCells.el);
  const rT=mkRange(ctrl,L.stage,0,100,0,1,color);
  const bPlay=mkBtn(L.play,true,color);ctrl.appendChild(bPlay);
  // Playback position is a float here, NOT in the slider: the range has step=1, so
  // writing a sub-step increment into it snaps back and nothing ever moves.
  let playing=false,tPos=0;
  const St=SIMS.mitosis={raf:null};
  rT.inp.addEventListener('input',function(){tPos=rT.val;playing=false;});
  bPlay.addEventListener('click',function(){if(tPos>=100)tPos=0;playing=!playing;});
  // Both divisions run on the SAME slider, side by side, so every stage can be
  // compared directly — that is the whole point of the pairing.
  const RED='#e11d48',BLUE='#2563eb',RED2='#f472b6',BLUE2='#38bdf8';
  const colW=W/2,cxM=W*0.25,cxE=W*0.75,ccy=214,R=Math.min(colW*0.30,86);
  // Split layouts are sized from the half-column so daughter cells can never
  // spill past the divider or the canvas edge on a narrow screen.
  const HALF=colW/2-10;
  const R2=Math.min(R*0.78,HALF*0.46),SEP=HALF-R2;                    // two cells
  const R4=Math.min(R*0.52,HALF*0.26),D4=(HALF-R4)/1.5;               // four cells
  const lerp=(a,b,f)=>a+(b-a)*f,clamp01=v=>v<0?0:v>1?1:v;
  function membrane(x,y,r,a){
    ctx.save();ctx.globalAlpha=a;
    const g=ctx.createRadialGradient(x-r*0.35,y-r*0.4,r*0.05,x,y,r);
    g.addColorStop(0,'rgba(255,255,255,0.98)');g.addColorStop(1,'rgba(233,231,242,0.9)');
    ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.strokeStyle='rgba(110,95,140,0.6)';ctx.lineWidth=2;ctx.setLineDash([3,3]);ctx.stroke();ctx.setLineDash([]);
    ctx.restore();
  }
  function nucleus(x,y,r,a){
    if(a<=0.03)return;
    ctx.save();ctx.globalAlpha=a;ctx.strokeStyle='rgba(124,58,180,0.85)';ctx.lineWidth=1.6;
    ctx.setLineDash([5,4]);ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.restore();
  }
  function pole(x,y,a){
    ctx.save();ctx.globalAlpha=a;
    ctx.strokeStyle='rgba(100,100,125,0.5)';ctx.lineWidth=1.2;
    for(let k=0;k<8;k++){const q=k*Math.PI/4;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+Math.cos(q)*9,y+Math.sin(q)*9);ctx.stroke();}
    ctx.fillStyle='rgba(90,90,115,0.9)';ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fill();ctx.restore();
  }
  function spindle(x,y,rx,a){
    if(a<=0.03)return;
    ctx.save();ctx.globalAlpha=a;ctx.strokeStyle='rgba(120,120,145,0.35)';ctx.lineWidth=1;
    for(let k=-2;k<=2;k++){ctx.beginPath();ctx.moveTo(x-rx,y);ctx.quadraticCurveTo(x,y+k*15,x+rx,y);ctx.stroke();}
    ctx.restore();pole(x-rx,y,a);pole(x+rx,y,a);
  }
  function plate(x,y,r,a){
    ctx.save();ctx.globalAlpha=a;ctx.strokeStyle='rgba(120,110,150,0.55)';ctx.lineWidth=1.4;ctx.setLineDash([4,5]);
    ctx.beginPath();ctx.moveTo(x,y-r);ctx.lineTo(x,y+r);ctx.stroke();ctx.setLineDash([]);ctx.restore();
  }
  // One chromatid: a rounded arm pinched at the centromere. `tip` recolours the
  // bottom of the arm — that is how a crossed-over piece is shown.
  function chromatid(x,y,s,col,lean,tip){
    ctx.lineCap='round';ctx.lineWidth=Math.max(4,s*0.34);ctx.strokeStyle=col;
    ctx.beginPath();ctx.moveTo(x-lean*s*0.40,y-s);ctx.quadraticCurveTo(x-lean*s*0.05,y-s*0.22,x,y);
    ctx.quadraticCurveTo(x+lean*s*0.05,y+s*0.22,x+lean*s*0.40,y+s);ctx.stroke();
    if(tip){ctx.strokeStyle=tip;ctx.beginPath();ctx.moveTo(x+lean*s*0.22,y+s*0.60);ctx.lineTo(x+lean*s*0.40,y+s);ctx.stroke();}
  }
  function chromX(x,y,s,col,tip){
    chromatid(x,y,s,col,1,tip);chromatid(x,y,s,col,-1,null);
    ctx.beginPath();ctx.arc(x,y,Math.max(2,s*0.13),0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,0.92)';ctx.fill();
  }
  function chromI(x,y,s,col,tip){chromatid(x,y,s,col,0.5,tip);}
  function spark(x,y){
    ctx.strokeStyle='#f59e0b';ctx.lineWidth=2;ctx.lineCap='round';
    for(let k=0;k<4;k++){const q=k*Math.PI/4;ctx.beginPath();ctx.moveTo(x-Math.cos(q)*7,y-Math.sin(q)*7);ctx.lineTo(x+Math.cos(q)*7,y+Math.sin(q)*7);ctx.stroke();}
  }
  const MIT=[
    [0,   'Interphase',   'DNA is copied: each chromosome becomes 2 sister chromatids'],
    [0.16,'Prophase',     'Chromosomes condense, nuclear envelope breaks down'],
    [0.34,'Metaphase',    'All chromosomes line up SINGLE file on the equator'],
    [0.50,'Anaphase',     'SISTER chromatids are pulled apart'],
    [0.72,'Telophase',    'Nuclei reform and the cell pinches in two'],
    [0.88,'2 cells (2n)', 'Two daughters, diploid and genetically identical']
  ];
  const MEI=[
    [0,   'Interphase',    'DNA is copied once — exactly as in mitosis'],
    [0.12,'Prophase I',    'Homologues PAIR UP and swap pieces (crossing over)'],
    [0.26,'Metaphase I',   'Pairs line up DOUBLE file, each pair facing at random'],
    [0.38,'Anaphase I',    'WHOLE homologues separate — sisters stay joined'],
    [0.52,'Telophase I',   'Two cells, already haploid but still doubled'],
    [0.62,'Prophase II',   'No second DNA copy — straight into division two'],
    [0.70,'Metaphase II',  'Chromosomes line up again, in both cells'],
    [0.80,'Anaphase II',   'Now the sister chromatids separate'],
    [0.90,'4 cells (n)',   'Four haploid gametes, every one a different mix']
  ];
  function stageAt(defs,t){
    let i=0;while(i<defs.length-1&&t>=defs[i+1][0])i++;
    const a=defs[i][0],b=(i+1<defs.length)?defs[i+1][0]:1.0001;
    return {i,f:clamp01((t-a)/(b-a)),name:defs[i][1],cap:defs[i][2],n:defs.length};
  }
  function header(x,title,stage){
    ctx.textAlign='center';
    ctx.fillStyle='rgba(70,58,95,0.95)';ctx.font='bold 14px system-ui';ctx.fillText(title,x,25);
    ctx.fillStyle=C;ctx.font='bold 13px system-ui';ctx.fillText(stage,x,46);
  }
  function caption(x,txt){
    ctx.textAlign='center';ctx.fillStyle='rgba(85,72,110,0.9)';ctx.font='11px system-ui';
    const max=colW-24;let s=txt;
    while(ctx.measureText(s).width>max&&s.length>8)s=s.slice(0,-2);
    ctx.fillText(s===txt?txt:s+'…',x,H-46);
  }
  function strip(x,n,idx){
    const w=Math.min(colW-46,n*24),x0=x-w/2,y=H-24;
    ctx.strokeStyle='rgba(150,140,175,0.4)';ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(x0,y);ctx.lineTo(x0+w,y);ctx.stroke();
    for(let i=0;i<n;i++){
      const px=x0+(n===1?w/2:i*w/(n-1));
      ctx.beginPath();ctx.arc(px,y,i===idx?6:4,0,Math.PI*2);
      ctx.fillStyle=i<idx?'rgba(147,51,234,0.42)':(i===idx?C:'rgba(186,178,205,0.7)');ctx.fill();
    }
    ctx.fillStyle='rgba(120,110,145,0.9)';ctx.font='10px system-ui';ctx.textAlign='center';
    ctx.fillText((idx+1)+'/'+n,x,y-13);
  }
  function drawMit(t){
    const s=stageAt(MIT,t),x=cxM,S=17;
    let cells=1;
    if(s.i===0){
      membrane(x,ccy,R,1);nucleus(x,ccy,R*0.7,1);
      if(s.f<0.5){chromI(x-24,ccy,S,RED);chromI(x+24,ccy,S,BLUE);}
      else{chromX(x-26,ccy,S,RED);chromX(x+26,ccy,S,BLUE);}
    }else if(s.i===1){
      membrane(x,ccy,R,1);nucleus(x,ccy,R*0.7,1-s.f);spindle(x,ccy,R*0.94,s.f);
      chromX(x-28,ccy-8,S,RED);chromX(x+28,ccy+8,S,BLUE);
    }else if(s.i===2){
      membrane(x,ccy,R,1);spindle(x,ccy,R*0.94,1);plate(x,ccy,R*0.8,1);
      chromX(x,ccy-28,S,RED);chromX(x,ccy+28,S,BLUE);
    }else if(s.i===3){
      membrane(x,ccy,R,1);spindle(x,ccy,R*0.94,1);
      const o=lerp(6,R*0.66,s.f);
      chromI(x-o,ccy-26,S,RED);chromI(x+o,ccy-26,S,RED);
      chromI(x-o,ccy+26,S,BLUE);chromI(x+o,ccy+26,S,BLUE);
    }else if(s.i===4){
      const sep=lerp(R2*0.2,SEP,s.f),r2=lerp(R,R2,s.f);
      membrane(x-sep,ccy,r2,1);membrane(x+sep,ccy,r2,1);
      nucleus(x-sep,ccy,r2*0.62,s.f);nucleus(x+sep,ccy,r2*0.62,s.f);
      [-1,1].forEach(function(d){chromI(x+d*sep-13,ccy,S-2,RED);chromI(x+d*sep+13,ccy,S-2,BLUE);});
      cells=s.f>0.45?2:1;
    }else{
      cells=2;
      [-1,1].forEach(function(d){
        membrane(x+d*SEP,ccy,R2,1);nucleus(x+d*SEP,ccy,R2*0.66,1);
        chromI(x+d*SEP-13,ccy,S-2,RED);chromI(x+d*SEP+13,ccy,S-2,BLUE);
      });
    }
    header(x,'MITOSIS',s.name);caption(x,s.cap);strip(x,s.n,s.i);
    return {name:s.name,cells:cells};
  }
  function drawMei(t){
    const s=stageAt(MEI,t),x=cxE,S=16,s2=13;
    // after crossing over the tips are swapped, and stay swapped to the end
    const xo=t>=MEI[1][0]+0.06;
    const tipR=xo?BLUE:null,tipB=xo?RED:null;
    let cells=1;
    if(s.i===0){
      membrane(x,ccy,R,1);nucleus(x,ccy,R*0.7,1);
      if(s.f<0.5){chromI(x-38,ccy,S,RED);chromI(x-13,ccy,S,BLUE);chromI(x+13,ccy,s2,RED2);chromI(x+38,ccy,s2,BLUE2);}
      else{chromX(x-40,ccy,S,RED);chromX(x-14,ccy,S,BLUE);chromX(x+14,ccy,s2,RED2);chromX(x+40,ccy,s2,BLUE2);}
    }else if(s.i===1){
      membrane(x,ccy,R,1);nucleus(x,ccy,R*0.7,1-s.f);spindle(x,ccy,R*0.94,s.f);
      const gap=lerp(26,15,clamp01(s.f*2));      // homologues drift together into pairs
      chromX(x-gap-14,ccy-6,S,RED,tipR);chromX(x-gap+14,ccy-6,S,BLUE,tipB);
      chromX(x+gap-12,ccy+30,s2,RED2);chromX(x+gap+12,ccy+30,s2,BLUE2);
      if(s.f>0.35&&s.f<0.85)spark(x-gap,ccy+6);
    }else if(s.i===2){
      membrane(x,ccy,R,1);spindle(x,ccy,R*0.94,1);plate(x,ccy,R*0.8,1);
      chromX(x-15,ccy-30,S,RED,tipR);chromX(x+15,ccy-30,S,BLUE,tipB);
      chromX(x-14,ccy+30,s2,BLUE2);chromX(x+14,ccy+30,s2,RED2);
    }else if(s.i===3){
      membrane(x,ccy,R,1);spindle(x,ccy,R*0.94,1);
      const o=lerp(15,R*0.62,s.f);
      chromX(x-o,ccy-28,S,RED,tipR);chromX(x+o,ccy-28,S,BLUE,tipB);
      chromX(x-o,ccy+28,s2,BLUE2);chromX(x+o,ccy+28,s2,RED2);
    }else if(s.i<8){
      const sep=(s.i===4)?lerp(R2*0.2,SEP,s.f):SEP,r2=(s.i===4)?lerp(R,R2,s.f):R2;cells=2;
      membrane(x-sep,ccy,r2,1);membrane(x+sep,ccy,r2,1);
      if(s.i===4){nucleus(x-sep,ccy,r2*0.62,s.f);nucleus(x+sep,ccy,r2*0.62,s.f);}
      if(s.i===5){nucleus(x-sep,ccy,r2*0.62,1-s.f);nucleus(x+sep,ccy,r2*0.62,1-s.f);
        spindle(x-sep,ccy,r2*0.9,s.f);spindle(x+sep,ccy,r2*0.9,s.f);}
      if(s.i>=6){spindle(x-sep,ccy,r2*0.9,1);spindle(x+sep,ccy,r2*0.9,1);}
      if(s.i===6){plate(x-sep,ccy,r2*0.75,1);plate(x+sep,ccy,r2*0.75,1);}
      if(s.i<7){
        chromX(x-sep,ccy-18,S-2,RED,tipR);chromX(x-sep,ccy+18,s2,BLUE2);
        chromX(x+sep,ccy-18,S-2,BLUE,tipB);chromX(x+sep,ccy+18,s2,RED2);
      }else{
        const o=lerp(6,r2*0.55,s.f);
        chromI(x-sep-o,ccy-18,S-2,RED,tipR);chromI(x-sep+o,ccy-18,S-2,RED,tipR);
        chromI(x-sep-o,ccy+18,s2,BLUE2);chromI(x-sep+o,ccy+18,s2,BLUE2);
        chromI(x+sep-o,ccy-18,S-2,BLUE,tipB);chromI(x+sep+o,ccy-18,S-2,BLUE,tipB);
        chromI(x+sep-o,ccy+18,s2,RED2);chromI(x+sep+o,ccy+18,s2,RED2);
      }
    }else{
      cells=4;
      const d=D4,r2=R4,xs=[x-1.5*d,x-0.5*d,x+0.5*d,x+1.5*d];
      const pair=[[RED,tipR,BLUE2],[RED,tipR,BLUE2],[BLUE,tipB,RED2],[BLUE,tipB,RED2]];
      for(let i=0;i<4;i++){
        membrane(xs[i],ccy,r2,1);nucleus(xs[i],ccy,r2*0.66,1);
        chromI(xs[i]-9,ccy,12,pair[i][0],pair[i][1]);chromI(xs[i]+9,ccy,10,pair[i][2]);
      }
    }
    header(x,'MEIOSIS',s.name);caption(x,s.cap);strip(x,s.n,s.i);
    return {name:s.name,cells:cells};
  }
  function frame(){
    if(playing){tPos+=0.32;if(tPos>=100){tPos=100;playing=false;}
      rT.inp.value=Math.round(tPos);rT.v.textContent=Math.round(tPos);}
    ctx.clearRect(0,0,W,H);
    const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#fbf7ff');bg.addColorStop(1,'#f1e9fa');
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.fillStyle='rgba(147,51,234,0.04)';ctx.fillRect(W/2,0,W/2,H);
    ctx.strokeStyle='rgba(130,115,160,0.35)';ctx.lineWidth=1.5;
    ctx.beginPath();ctx.moveTo(W/2,8);ctx.lineTo(W/2,H-40);ctx.stroke();
    const a=drawMit(tPos/100),b=drawMei(tPos/100);
    pPhase.set(a.name+'  ·  '+b.name);pCells.set(a.cells+'  ·  '+b.cells);
    St.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simSorting(container,color,lvl){
  const W=getSimWidth(container),H=260;
  const {canvas,ctx,dpr}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('sorting',lvl);
  const pAlgo=pill(L.algo); const pComp=pill(L.comps); const pSwap=pill(L.swaps);
  pRow.appendChild(pAlgo.el); pRow.appendChild(pComp.el); pRow.appendChild(pSwap.el);

  const bBubble=mkBtn(L.bubble,true,color);
  const bMerge=mkBtn(L.merge);
  const bRand=mkBtn('↺ '+L.shuffle);
  const rN=mkRange(ctrl,L.size,10,80,40,5,color);
  [bBubble,bMerge,bRand].forEach(b=>ctrl.prepend(b));

  let arr=[], n=40, gen=null, active=false, comps=0, swaps=0;
  function shuffle(){n=rN.val;arr=Array.from({length:n},()=>Math.floor(Math.random()*95)+5);comps=0;swaps=0;active=false;gen=null;pComp.set(0);pSwap.set(0);}

  function* bubble(a){
    for(let i=0;i<a.length;i++) for(let j=0;j<a.length-i-1;j++){
      comps++;if(a[j]>a[j+1]){[a[j],a[j+1]]=[a[j+1],a[j]];swaps++;}
      yield;
    }
  }
  function* merge(a){
    function*ms(l,r){
      if(l>=r)return;const m=(l+r)>>1;yield*ms(l,m);yield*ms(m+1,r);
      const L=a.slice(l,m+1),R=a.slice(m+1,r+1);
      let i=0,j=0,k=l;
      while(i<L.length&&j<R.length){comps++;if(L[i]<=R[j])a[k++]=L[i++];else{a[k++]=R[j++];swaps++;}yield;}
      while(i<L.length){a[k++]=L[i++];yield;}
      while(j<R.length){a[k++]=R[j++];yield;}
    }
    yield*ms(0,a.length-1);
  }

  bBubble.addEventListener('click',()=>{shuffle();pAlgo.set('Bubble O(n²)');gen=bubble(arr);active=true;});
  bMerge.addEventListener('click',()=>{shuffle();pAlgo.set('Merge O(n log n)');gen=merge(arr);active=true;});
  bRand.addEventListener('click',shuffle);
  rN.inp.addEventListener('input',shuffle);
  shuffle();

  const S=SIMS.sorting={raf:null,timer:null};
  function frame(){
    ctx.clearRect(0,0,W,H);
    const bw=W/arr.length;
    arr.forEach((v,i)=>{
      const bh=(v/100)*(H-12);
      ctx.fillStyle=`hsl(${210+i*120/arr.length},65%,55%)`;
      ctx.fillRect(i*bw,(H-6)-bh,Math.max(1,bw-1.5),bh);
    });
    if(active&&gen){
      const steps=gen===bubble?4:10;
      for(let i=0;i<steps;i++){const r=gen.next();if(r.done){active=false;break;}}
      pComp.set(comps);pSwap.set(swaps);
    }
    S.timer=setTimeout(()=>{S.raf=requestAnimationFrame(frame);},16);
  }
  frame();
}

function simML(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('ml', lvl);
  const pEpoch = pill(L.epoch); const pLoss = pill(L.loss); const pAcc = pill(L.acc);
  pRow.appendChild(pEpoch.el); pRow.appendChild(pLoss.el); pRow.appendChild(pAcc.el);
  const rLR   = mkRange(ctrl, L.lr, 1, 10, 4, 1, color);
  const rHid  = mkRange(ctrl, L.hid,  2, 12, 5, 1, color);
  const bReset = mkBtn('↺ ' + L.reset, true, color);
  ctrl.appendChild(bReset);

  // XOR-style dataset: 4 clusters
  function makeData() {
    const pts = [];
    const centres = [[0.25,0.25,0],[0.75,0.75,0],[0.25,0.75,1],[0.75,0.25,1]];
    centres.forEach(([cx,cy,lbl]) => {
      for (let i = 0; i < 18; i++)
        pts.push({ x: cx + (Math.random()-.5)*.28, y: cy + (Math.random()-.5)*.28, lbl });
    });
    return pts;
  }

  // Tiny 2→H→1 network
  let W1, b1, W2, b2, epoch, loss, data;
  function sigmoid(z) { return 1/(1+Math.exp(-z)); }
  // inputs centred to [-1,1] so the net reliably escapes the XOR 50% saddle
  const cen = v => (v - 0.5) * 2;
  function initNet() {
    const H = rHid.val;
    W1 = Array.from({length:H}, ()=>[Math.random()*2-1, Math.random()*2-1]);
    b1 = Array.from({length:H}, ()=>Math.random()-0.5);
    W2 = Array.from({length:H}, ()=>Math.random()*2-1);
    b2 = [Math.random()*.4-.2];
    epoch = 0; loss = 1; data = makeData();
  }
  bReset.addEventListener('click', initNet);
  rHid.inp.addEventListener('input', initNet);
  initNet();

  function forward(x, y) {
    const X = cen(x), Y = cen(y);
    const h = W1.map((w,i) => sigmoid(w[0]*X + w[1]*Y + b1[i]));
    const o = sigmoid(h.reduce((s,hi,i) => s + W2[i]*hi, b2[0]));
    return { h, o };
  }

  function trainStep() {
    const lr = rLR.val * 0.03;
    let totalLoss = 0;
    // mini-batch = full data
    data.forEach(pt => {
      const X = cen(pt.x), Y = cen(pt.y);
      const { h, o } = forward(pt.x, pt.y);
      const err = o - pt.lbl;
      totalLoss += err * err;
      // output layer gradient
      const dO = err * o * (1-o);
      // hidden layer gradients (use pre-update W2)
      const dH = W2.map((w,i) => dO * w * h[i] * (1-h[i]));
      // update output weights
      W2 = W2.map((w,i) => w - lr * dO * h[i]);
      b2[0] -= lr * dO;
      // update hidden weights (centred inputs)
      W1 = W1.map((w,i) => [w[0] - lr*dH[i]*X, w[1] - lr*dH[i]*Y]);
      b1 = b1.map((b,i) => b - lr*dH[i]);
    });
    loss = Math.sqrt(totalLoss / data.length);
    epoch++;
  }

  const S = SIMS.ml = { raf: null };
  let frameCount = 0;

  function frame() {
    frameCount++;
    // train several steps per frame
    for (let i = 0; i < 8; i++) trainStep();

    ctx.clearRect(0, 0, W, H);
    const PAD = 30, PW = W-PAD*2, PH = H-PAD*2;

    // decision boundary heatmap
    const res = 28;
    for (let i = 0; i < res; i++) {
      for (let j = 0; j < res; j++) {
        const nx = i/res, ny = j/res;
        const { o } = forward(nx, ny);
        const r = Math.round(o*200+30), b2c = Math.round((1-o)*200+30);
        ctx.fillStyle = `rgba(${r},80,${b2c},0.55)`;
        ctx.fillRect(PAD + nx*PW, PAD + ny*PH, PW/res+1, PH/res+1);
      }
    }

    // data points
    let correct = 0;
    data.forEach(pt => {
      const px = PAD + pt.x*PW, py = PAD + pt.y*PH;
      const { o } = forward(pt.x, pt.y);
      const pred = o > 0.5 ? 1 : 0;
      if (pred === pt.lbl) correct++;
      ctx.beginPath(); ctx.arc(px, py, 6, 0, Math.PI*2);
      ctx.fillStyle = pt.lbl ? '#f59e0b' : '#6366f1';
      ctx.fill();
      ctx.strokeStyle = pred===pt.lbl ? '#fff' : '#ef4444';
      ctx.lineWidth = 2; ctx.stroke();
    });

    // network diagram (right side overlay)
    const nx0 = W - 90, ny0 = H/2;
    const layers = [2, rHid.val, 1];
    const xPos = [nx0, nx0+28, nx0+56];
    const nodeR = 5;
    ctx.globalAlpha = 0.7;
    layers.forEach((n, li) => {
      const yOff = H/(n+1);
      for (let i = 0; i < n; i++) {
        const ny2 = yOff*(i+1);
        if (li < layers.length-1) {
          const nextN = layers[li+1];
          const nextYOff = H/(nextN+1);
          for (let j = 0; j < nextN; j++) {
            ctx.beginPath();
            ctx.moveTo(xPos[li], ny2);
            ctx.lineTo(xPos[li+1], nextYOff*(j+1));
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.lineWidth = 1; ctx.stroke();
          }
        }
        ctx.beginPath(); ctx.arc(xPos[li], ny2, nodeR, 0, Math.PI*2);
        ctx.fillStyle = li===0?'#6366f1':li===1?color:'#f59e0b';
        ctx.fill();
      }
    });
    ctx.globalAlpha = 1;

    const acc = Math.round(correct/data.length*100);
    pEpoch.set(epoch); pLoss.set(loss.toFixed(3)); pAcc.set(acc+'%');
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simCrypto(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('crypto', lvl);
  const pStep = pill(L.step); const pKey = pill(L.key);
  pRow.appendChild(pStep.el); pRow.appendChild(pKey.el);
  const bStart = mkBtn('▶ ' + L.run, true, color);
  const bReset = mkBtn('↺ ' + L.reset);
  ctrl.appendChild(bStart); ctrl.appendChild(bReset);

  // Diffie-Hellman with small numbers for visualisation
  const p = 23, g = 5;
  let state = 'idle', step = 0, animT = 0;
  let alicePriv, bobPriv, alicePub, bobPub, sharedA, sharedB;
  let msgX = -1, msgY = -1, msgTx = -1, msgTy = -1, msgProg = 0, msgLabel = '';
  let msgCol = '#fff', msgs = [];

  function reset() {
    state = 'idle'; step = 0; animT = 0; msgs = [];
    alicePriv = 2 + Math.floor(Math.random()*8);
    bobPriv   = 2 + Math.floor(Math.random()*8);
    alicePub  = Math.pow(g, alicePriv) % p;
    bobPub    = Math.pow(g, bobPriv)   % p;
    sharedA   = Math.pow(bobPub,   alicePriv) % p;
    sharedB   = Math.pow(alicePub, bobPriv)   % p;
  }
  reset();

  bStart.addEventListener('click', () => { if (state==='idle'||state==='done') { reset(); state='running'; step=0; } });
  bReset.addEventListener('click', () => { reset(); });

  const STEPS = [
    () => ({ from:'alice', to:'public', label:`g=${g}, p=${p}`, col:'#94a3b8', note:'Public parameters agreed' }),
    () => ({ from:'alice', to:'bob',    label:`A = g^a mod p = ${alicePub}`, col:'#818cf8', note:`Alice sends public key A=${alicePub}` }),
    () => ({ from:'bob',   to:'alice',  label:`B = g^b mod p = ${bobPub}`,   col:'#34d399', note:`Bob sends public key B=${bobPub}` }),
    () => ({ from:'alice', to:'alice',  label:`K = B^a mod p = ${sharedA}`,  col:'#fbbf24', note:`Alice computes shared key` }),
    () => ({ from:'bob',   to:'bob',    label:`K = A^b mod p = ${sharedB}`,  col:'#fbbf24', note:`Bob computes shared key` }),
  ];

  const S = SIMS.crypto = { raf: null };
  let frameCount = 0;

  function frame() {
    frameCount++; animT++;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);

    const aliceX = 80, bobX = W-80, midY = H/2, personR = 28;

    // draw public channel bar
    ctx.fillStyle = 'rgba(148,163,184,0.08)';
    ctx.fillRect(aliceX+personR+5, midY-14, bobX-aliceX-personR*2-10, 28);
    ctx.fillStyle = 'rgba(148,163,184,0.3)';
    ctx.font = '9px Nunito,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('PUBLIC CHANNEL (eavesdropper can see)', W/2, midY-18);

    // Alice
    ctx.beginPath(); ctx.arc(aliceX, midY, personR, 0, Math.PI*2);
    ctx.fillStyle = '#312e81'; ctx.fill();
    ctx.strokeStyle = '#818cf8'; ctx.lineWidth = 2; ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 11px Nunito,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('Alice', aliceX, midY+4);
    ctx.fillStyle = '#818cf8'; ctx.font = '10px Nunito,sans-serif';
    ctx.fillText(`secret a=${alicePriv}`, aliceX, midY+personR+14);

    // Bob
    ctx.beginPath(); ctx.arc(bobX, midY, personR, 0, Math.PI*2);
    ctx.fillStyle = '#064e3b'; ctx.fill();
    ctx.strokeStyle = '#34d399'; ctx.lineWidth = 2; ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 11px Nunito,sans-serif';
    ctx.fillText('Bob', bobX, midY+4);
    ctx.fillStyle = '#34d399'; ctx.font = '10px Nunito,sans-serif';
    ctx.fillText(`secret b=${bobPriv}`, bobX, midY+personR+14);

    // Eavesdropper
    const eaveX = W/2, eaveY = 36;
    ctx.beginPath(); ctx.arc(eaveX, eaveY, 16, 0, Math.PI*2);
    ctx.fillStyle = '#450a0a'; ctx.fill();
    ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.fillStyle = '#ef4444'; ctx.font = 'bold 9px Nunito,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('Eve', eaveX, eaveY+3);
    ctx.fillStyle = 'rgba(239,68,68,0.5)'; ctx.font = '8px Nunito,sans-serif';
    ctx.fillText('sees everything!', eaveX, eaveY+20);

    // step messages
    msgs.forEach((m, mi) => {
      ctx.fillStyle = m.col;
      ctx.font = 'bold 10px Nunito,sans-serif'; ctx.textAlign = 'center';
      ctx.fillText(m.note, W/2, H-20-mi*16);
    });

    // animate current message packet
    if (state === 'running') {
      if (frameCount % 70 === 0 && step < STEPS.length) {
        const s = STEPS[step]();
        msgs.unshift({ note: s.note, col: s.col });
        if (msgs.length > 4) msgs.pop();
        step++;
        if (step >= STEPS.length) state = 'done';
      }
      // packet animation
      const prog = (frameCount % 70) / 70;
      if (step > 0 && step <= STEPS.length) {
        const s = STEPS[step-1]();
        const fromX = s.from==='alice' ? aliceX : bobX;
        const toX   = s.to==='bob' ? bobX : s.to==='alice' ? aliceX : W/2;
        const px = fromX + (toX - fromX) * prog;
        const py = midY + Math.sin(prog * Math.PI) * -35;
        ctx.beginPath(); ctx.arc(px, py, 8, 0, Math.PI*2);
        ctx.fillStyle = s.col; ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = 'bold 7px Nunito,sans-serif'; ctx.textAlign = 'center';
        ctx.fillText(s.label.split('=').pop(), px, py+3);
      }
    }

    if (state === 'done' && sharedA === sharedB) {
      ctx.fillStyle = 'rgba(251,191,36,0.15)';
      ctx.fillRect(aliceX-35, midY-personR-35, 70, 22);
      ctx.fillRect(bobX-35,   midY-personR-35, 70, 22);
      ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 11px Nunito,sans-serif'; ctx.textAlign = 'center';
      ctx.fillText(`🔑 K=${sharedA}`, aliceX, midY-personR-20);
      ctx.fillText(`🔑 K=${sharedB}`, bobX,   midY-personR-20);
    }

    pStep.set(step + ' / ' + STEPS.length);
    pKey.set(state==='done' ? sharedA : '?');
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simComplexity(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('complexity', lvl);
  const pOps = pill(L.ops); const pClass = pill(L.cls); const pN = pill(L.nval);
  pRow.appendChild(pOps.el); pRow.appendChild(pClass.el); pRow.appendChild(pN.el);
  const rN    = mkRange(ctrl, L.n, 2, 22, 8, 1, color);
  // label was off by one: slider value 1 selects ALGOS[0], which is O(log n)
  const rAlgo = mkRange(ctrl, L.algo, 1, 5, 2, 1, color);
  const bRun  = mkBtn('▶ ' + L.run, true, color);
  ctrl.appendChild(bRun);

  const ALGOS = [
    { name:'O(log n)',  col:'#34d399', ops: n => Math.ceil(Math.log2(n+1)),          ex:'Binary search' },
    { name:'O(n)',      col:'#60a5fa', ops: n => n,                                   ex:'Linear scan' },
    { name:'O(n log n)',col:'#a78bfa', ops: n => Math.ceil(n*Math.log2(n+1)),         ex:'Merge sort' },
    { name:'O(n²)',     col:'#f59e0b', ops: n => n*n,                                 ex:'Bubble sort' },
    { name:'O(2ⁿ)',     col:'#ef4444', ops: n => Math.min(Math.pow(2,n), 1e9),        ex:'Brute force NP' },
  ];

  let running = false, progress = 0, currentOps = 0;
  bRun.addEventListener('click', () => { running = true; progress = 0; currentOps = 0; });

  const S = SIMS.complexity = { raf: null };
  let t = 0;

  function frame() {
    t++;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);

    const PAD = 48, PW = W-PAD*2, PH = H-PAD*2;
    const n = rN.val;
    const maxN = 22;

    // axes
    ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(PAD, PAD); ctx.lineTo(PAD, PAD+PH); ctx.lineTo(PAD+PW, PAD+PH); ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.font = '9px Nunito,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('Input size n →', PAD+PW/2, PAD+PH+16);
    ctx.save(); ctx.translate(12, PAD+PH/2); ctx.rotate(-Math.PI/2);
    ctx.fillText('Operations', 0, 0); ctx.restore();

    // n gridline
    const nX = PAD + (n/maxN)*PW;
    ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.setLineDash([4,4]);
    ctx.beginPath(); ctx.moveTo(nX, PAD); ctx.lineTo(nX, PAD+PH); ctx.stroke();
    ctx.setLineDash([]);

    // draw all curves
    const selectedIdx = rAlgo.val - 1;
    const maxOps = ALGOS[selectedIdx].ops(maxN) || 1;
    const safeMax = Math.max(maxOps, 1);

    ALGOS.forEach((algo, ai) => {
      ctx.beginPath();
      for (let xi = 1; xi <= maxN; xi++) {
        const ops = algo.ops(xi);
        const px = PAD + (xi/maxN)*PW;
        const py = PAD + PH - Math.min((ops/safeMax)*PH, PH);
        xi === 1 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
      }
      ctx.strokeStyle = ai === selectedIdx ? algo.col : 'rgba(255,255,255,0.12)';
      ctx.lineWidth = ai === selectedIdx ? 2.5 : 1;
      ctx.stroke();

      // label at right end
      const lastOps = algo.ops(maxN);
      const lastY = PAD + PH - Math.min((lastOps/safeMax)*PH, PH);
      ctx.fillStyle = ai === selectedIdx ? algo.col : 'rgba(255,255,255,0.25)';
      ctx.font = ai === selectedIdx ? 'bold 10px Nunito,sans-serif' : '9px Nunito,sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(algo.name, PAD+PW+3, Math.max(PAD+8, Math.min(lastY, PAD+PH-2)));
    });

    // animated dot running along selected curve
    const algo = ALGOS[selectedIdx];
    const totalOps = algo.ops(n);
    if (running) {
      currentOps += Math.max(1, Math.ceil(totalOps/60));
      if (currentOps >= totalOps) { currentOps = totalOps; running = false; }
    }
    const dotOps = running ? currentOps : totalOps;
    const dotX = nX;
    const dotY = PAD + PH - Math.min((dotOps/safeMax)*PH, PH);
    ctx.beginPath(); ctx.arc(dotX, dotY, 7, 0, Math.PI*2);
    ctx.fillStyle = algo.col; ctx.fill();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.stroke();

    // info box
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(PAD+4, PAD+4, 175, 42);
    ctx.fillStyle = algo.col; ctx.font = 'bold 12px Nunito,sans-serif'; ctx.textAlign = 'left';
    ctx.fillText(algo.name + ' - ' + algo.ex, PAD+10, PAD+18);
    ctx.fillStyle = '#cbd5e1'; ctx.font = '10px Nunito,sans-serif';
    ctx.fillText(`n=${n}  →  ${totalOps.toLocaleString()} operations`, PAD+10, PAD+34);

    // complexity class badge
    const cls = selectedIdx <= 2 ? 'P (tractable)' : selectedIdx === 3 ? 'P (slow)' : 'NP-hard ⚠️';
    const clsCol = selectedIdx <= 3 ? '#34d399' : '#ef4444';
    pOps.set(totalOps >= 1e9 ? '>1 billion' : totalOps.toLocaleString());
    pClass.set(cls); pN.set(n);

    // draw class badge on canvas
    ctx.fillStyle = selectedIdx === 4 ? 'rgba(239,68,68,0.15)' : 'rgba(52,211,153,0.1)';
    ctx.fillRect(W-130, PAD+4, 82, 22);
    ctx.fillStyle = clsCol; ctx.font = 'bold 10px Nunito,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(cls, W-89, PAD+18);

    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simClimate(container,color,lvl){
  const W=getSimWidth(container),H=280;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('climate',lvl);
  const pCO2=pill(L.c); const pF=pill(L.forcing); const pDT=pill(L.dt);
  pRow.appendChild(pCO2.el); pRow.appendChild(pF.el); pRow.appendChild(pDT.el);

  const rC=mkRange(ctrl,L.co2,280,800,280,5,color);
  const bPre=mkBtn('↺ '+L.pre);
  const bNow=mkBtn(L.now,true,color);
  ctrl.appendChild(bPre); ctrl.appendChild(bNow);

  bPre.addEventListener('click',()=>{rC.inp.value=280;rC.v.textContent='280';});
  bNow.addEventListener('click',()=>{rC.inp.value=420;rC.v.textContent='420';});

  let t=0;
  const S=SIMS.climate={raf:null};
  function frame(){
    ctx.clearRect(0,0,W,H);
    t+=0.03;
    const co2=rC.val;
    const dF=5.35*Math.log(co2/280);
    const dT=dF*0.8;

    // Sky gradient
    const skyH=H*0.72;
    const g=ctx.createLinearGradient(0,0,0,skyH);
    const warmth=Math.min((co2-280)/520,1);
    g.addColorStop(0,`hsl(${200-warmth*30},${60+warmth*20}%,${70-warmth*15}%)`);
    g.addColorStop(1,`hsl(${200-warmth*20},40%,85%)`);
    ctx.fillStyle=g;ctx.fillRect(0,0,W,skyH);

    // Ground
    const groundH=H*0.28;
    const gh=ctx.createLinearGradient(0,skyH,0,H);
    gh.addColorStop(0,`hsl(${120-warmth*40},${50+warmth*10}%,${35-warmth*8}%)`);
    gh.addColorStop(1,`hsl(${100-warmth*40},40%,25%)`);
    ctx.fillStyle=gh;ctx.fillRect(0,skyH,W,groundH);

    // Sun
    const sx=W*0.12,sy=H*0.17;
    const sg=ctx.createRadialGradient(sx,sy,0,sx,sy,25);
    sg.addColorStop(0,'rgba(255,240,80,1)');sg.addColorStop(1,'rgba(255,200,50,0)');
    ctx.beginPath();ctx.arc(sx,sy,22,0,Math.PI*2);ctx.fillStyle='#fbbf24';ctx.fill();
    for(let i=0;i<8;i++){const a=i/8*Math.PI*2+t*0.3;ctx.beginPath();ctx.moveTo(sx+26*Math.cos(a),sy+26*Math.sin(a));ctx.lineTo(sx+36*Math.cos(a),sy+36*Math.sin(a));ctx.strokeStyle='#fbbf24';ctx.lineWidth=2.5;ctx.stroke();}

    // Atmosphere layer (thicker = more CO₂)
    const atmoAlpha=0.08+(warmth*0.38);
    const atmoY=H*0.24, atmoH=H*0.16;
    ctx.fillStyle=`rgba(100,180,80,${atmoAlpha})`;
    ctx.fillRect(0,atmoY,W,atmoH);
    ctx.font='bold 11px Nunito,sans-serif';ctx.fillStyle=`rgba(0,80,0,${0.4+atmoAlpha})`;ctx.textAlign='center';
    ctx.fillText(`Atmosphere  CO₂: ${co2} ppm`,W/2,atmoY+atmoH*0.62);

    // Incoming solar rays (yellow dots)
    for(let i=0;i<5;i++){
      const prog=(t*0.38+i*0.2)%1;
      const rx=W*0.2+W*0.6*(i/4.5);const ry=sy+prog*(skyH*0.88-sy);
      ctx.beginPath();ctx.arc(rx,ry,3.5,0,Math.PI*2);ctx.fillStyle='rgba(255,220,40,0.85)';ctx.fill();
    }

    // Outgoing IR rays (orange) - some trapped
    for(let i=0;i<5;i++){
      const prog=(t*0.3+i*0.2)%1;
      const rx=W*0.25+W*0.5*(i/4.5);const ry=skyH-prog*(skyH*0.75);
      const trapped=warmth>0.3&&Math.random()<warmth*0.7;
      ctx.beginPath();ctx.arc(rx,ry,3.5,0,Math.PI*2);
      ctx.fillStyle=trapped?'rgba(255,80,30,0.85)':'rgba(255,160,60,0.65)';ctx.fill();
    }

    // Labels
    ctx.textAlign='left';ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='bold 12px Nunito,sans-serif';
    ctx.fillText('🟡 Solar radiation',W*0.02,H*0.55);
    ctx.fillStyle='rgba(255,120,50,0.9)';
    ctx.fillText('🔴 Trapped IR heat',W*0.02,H*0.62);

    // Ground label
    ctx.fillStyle='rgba(255,255,255,0.6)';ctx.textAlign='center';ctx.font='bold 11px Nunito,sans-serif';
    ctx.fillText(`Earth surface - ΔT: ${dT>0?'+':''}${dT.toFixed(2)} °C vs pre-industrial`,W/2,H*0.88);

    pCO2.set(co2+' ppm');pF.set(dF.toFixed(2)+' W/m²');pDT.set((dT>0?'+':'')+dT.toFixed(2)+'°C');
    S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simTectonics(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('tectonics', lvl);
  const pStress = pill(L.stress); const pTime = pill(L.time); const pEvent = pill(L.event);
  pRow.appendChild(pStress.el); pRow.appendChild(pTime.el); pRow.appendChild(pEvent.el);
  const rSpeed = mkRange(ctrl, L.speed, 1, 10, 4, 1, color);
  const rType  = mkRange(ctrl, L.type, 1, 3, 2, 1, color);
  const bQuake = mkBtn('⚡ ' + L.quake, true, color);
  ctrl.appendChild(bQuake);

  let stress = 0, myr = 0, lastEvent = 'none', quakeAnim = 0;
  let particles = [];
  for (let i = 0; i < 18; i++)
    particles.push({ x: Math.random()*W, y: 30+Math.random()*(H-60), side: Math.random()<.5?'L':'R', r: 3+Math.random()*3, col: `hsl(${20+Math.random()*30},${50+Math.random()*20}%,${35+Math.random()*20}%)` });

  bQuake.addEventListener('click', () => { stress = 0; quakeAnim = 40; lastEvent = 'M'+(4+Math.floor(Math.random()*4))+'.'+Math.floor(Math.random()*9)+' quake'; });

  const S = SIMS.tectonics = { raf: null };
  let t = 0;

  function frame() {
    t++; myr += 0.001 * rSpeed.val;
    stress = Math.min(100, stress + 0.08 * rSpeed.val);
    if (stress >= 100) { stress = 0; quakeAnim = 35; lastEvent = 'M'+(5+Math.floor(Math.random()*3))+'.'+Math.floor(Math.random()*9)+' quake'; }
    if (quakeAnim > 0) quakeAnim--;

    ctx.clearRect(0, 0, W, H);

    const type = rType.val; // 1=diverge 2=transform 3=converge
    const spd = rSpeed.val * 0.4;
    const midX = W / 2;
    const shake = quakeAnim > 0 ? (Math.random()-.5)*8*(quakeAnim/35) : 0;

    // Left plate
    const lx = shake * -1;
    ctx.fillStyle = '#78350f'; ctx.fillRect(lx, 0, midX+lx, H);
    // Right plate
    const rx = shake;
    ctx.fillStyle = '#92400e'; ctx.fillRect(midX+rx, 0, W-midX, H);

    // plate surface texture
    [lx, rx+midX].forEach((ox, si) => {
      ctx.fillStyle = si===0 ? '#a16207' : '#b45309';
      ctx.fillRect(ox + (si===0?0:0), 0, si===0?midX:W-midX, 22);
    });

    // boundary line
    const bCol = quakeAnim > 0 ? '#ef4444' : type===1?'#f59e0b':type===2?'#60a5fa':'#a855f7';
    ctx.strokeStyle = bCol; ctx.lineWidth = quakeAnim>0?4:2;
    ctx.setLineDash(type===2?[8,6]:[]);
    ctx.beginPath(); ctx.moveTo(midX+shake*.5, 0); ctx.lineTo(midX+shake*.5, H);
    ctx.stroke(); ctx.setLineDash([]);

    // boundary label
    const bLabels = ['','DIVERGENT ←→','TRANSFORM →|←','CONVERGENT →←'];
    ctx.fillStyle = bCol; ctx.font = 'bold 10px Nunito,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(bLabels[type], W/2, H-8);

    // move & draw particles (rock markers)
    particles.forEach(p => {
      if (p.side==='L') {
        p.x += type===1 ? -spd*0.5 : type===3 ? spd*0.3 : 0;
        if (p.x < -20) p.x = midX - 10;
      } else {
        p.x += type===1 ? spd*0.5 : type===3 ? -spd*0.3 : 0;
        if (p.x > W+20) p.x = midX + 10;
      }
      // transform: vertical movement
      if (type===2) { p.y += p.side==='L' ? -spd*0.4 : spd*0.4; if (p.y<10) p.y=H-10; if (p.y>H-10) p.y=10; }
      // quake shake
      const px = p.x + (quakeAnim>0?(Math.random()-.5)*5:0);
      const py = p.y + (quakeAnim>0?(Math.random()-.5)*5:0);
      ctx.beginPath(); ctx.arc(px, py, p.r, 0, Math.PI*2);
      ctx.fillStyle = p.col; ctx.fill();
    });

    // arrows showing plate motion
    const arrowY = H/2;
    const arrowCol = 'rgba(255,255,255,0.5)';
    const drawArrow = (x1,y,x2) => {
      ctx.beginPath(); ctx.moveTo(x1,y); ctx.lineTo(x2,y);
      ctx.strokeStyle=arrowCol; ctx.lineWidth=2; ctx.stroke();
      ctx.beginPath(); const dir=x2>x1?1:-1;
      ctx.moveTo(x2,y); ctx.lineTo(x2-dir*8,y-5); ctx.lineTo(x2-dir*8,y+5);
      ctx.fillStyle=arrowCol; ctx.fill();
    };
    if (type===1) { drawArrow(midX-20,arrowY,midX-60); drawArrow(midX+20,arrowY,midX+60); }
    else if (type===3) { drawArrow(midX-60,arrowY,midX-20); drawArrow(midX+60,arrowY,midX+20); }
    else { drawArrow(midX-70,arrowY-10,midX-20); drawArrow(midX+20,arrowY+10,midX+70); }

    // stress bar
    ctx.fillStyle='rgba(0,0,0,0.4)'; ctx.fillRect(10,10,120,12);
    ctx.fillStyle=`hsl(${120-stress*1.2},80%,50%)`; ctx.fillRect(10,10,stress*1.2,12);
    ctx.fillStyle='#fff'; ctx.font='9px Nunito,sans-serif'; ctx.textAlign='left';
    ctx.fillText('Stress: '+Math.round(stress)+'%', 13, 20);

    // quake flash
    if (quakeAnim > 0) {
      ctx.fillStyle = `rgba(239,68,68,${quakeAnim/35*0.25})`;
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle='#fef3c7'; ctx.font='bold 14px Nunito,sans-serif'; ctx.textAlign='center';
      ctx.fillText('⚡ '+lastEvent, W/2, H/2);
    }

    pStress.set(Math.round(stress)+'%'); pTime.set(myr.toFixed(1)); pEvent.set(lastEvent);
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simOcean(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('ocean', lvl);
  const pFlow = pill(L.flow); const pTemp = pill(L.temp); const pAMOC = pill(L.amoc);
  pRow.appendChild(pFlow.el); pRow.appendChild(pTemp.el); pRow.appendChild(pAMOC.el);
  const rWind   = mkRange(ctrl, L.wind, 1, 10, 5, 1, color);
  const rWarm   = mkRange(ctrl, L.warm, 0, 10, 2, 1, color);
  ctrl.appendChild(mkBtn(''));  // spacer

  // Particle field simulating gyre + thermohaline
  const N = 120;
  let parts = [];
  for (let i = 0; i < N; i++) {
    parts.push({ x: Math.random()*W, y: Math.random()*H, vx:0, vy:0, depth: Math.random(), age: Math.random()*100 });
  }

  const S = SIMS.ocean = { raf: null };
  let t = 0;

  function oceanVelocity(x, y, wind, warm) {
    // Surface gyre (wind-driven, clockwise NH)
    const cx = W/2, cy = H/2;
    const dx = x-cx, dy = y-cy;
    const r = Math.sqrt(dx*dx+dy*dy)+1;
    const gyre = wind * 0.018;
    let vx = gyre * ( dy/r);
    let vy = gyre * (-dx/r);
    // Gulf Stream: strong northward current on western boundary
    const gsStr = wind * 0.035;
    if (x < W*0.22) { vx += gsStr * 0.3; vy += -gsStr * (1-(x/(W*0.22))); }
    // Equatorial current: westward
    if (y > H*0.45 && y < H*0.65) { vx -= wind*0.012; }
    // AMOC weakening: reduce deep sinking in north
    const amocStr = Math.max(0, 1 - warm/12);
    if (y < H*0.25 && x > W*0.6) { vy += amocStr * wind * 0.02; }
    return { vx, vy };
  }

  function frame() {
    t++;
    const wind = rWind.val, warm = rWarm.val;
    ctx.clearRect(0, 0, W, H);

    // ocean background with temperature gradient
    for (let j = 0; j < H; j += 4) {
      const lat = 1 - j/H; // 0=south, 1=north
      const baseT = 28 - lat*20 - warm*lat*0.5;
      const hue = Math.max(200, 240 - baseT*4);
      ctx.fillStyle = `hsl(${hue},${60+warm*2}%,${15+baseT*.5}%)`;
      ctx.fillRect(0, j, W, 4);
    }

    // update & draw particles
    parts.forEach(p => {
      p.age++;
      const { vx, vy } = oceanVelocity(p.x, p.y, wind, warm);
      p.vx = p.vx*.85 + vx*.15; p.vy = p.vy*.85 + vy*.15;
      p.x = (p.x + p.vx + W) % W; p.y = (p.y + p.vy + H) % H;
      const spd = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
      const lat = 1 - p.y/H;
      const T = 28 - lat*20;
      const hue = T > 15 ? 30 : T > 5 ? 190 : 220;
      const alpha = Math.min(0.85, 0.3 + spd*8);
      ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI*2);
      ctx.fillStyle = `hsla(${hue},80%,65%,${alpha})`;
      ctx.fill();
      // draw velocity arrow every 30 frames
      if (p.age % 30 === 0 && spd > 0.1) {
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x + p.vx*12, p.y + p.vy*12);
        ctx.strokeStyle = `hsla(${hue},80%,80%,0.4)`;
        ctx.lineWidth = 1; ctx.stroke();
      }
    });

    // Labels
    const labels = [
      {x:W*.12, y:H*.35, t:'Gulf\nStream', c:'#fbbf24'},
      {x:W*.5,  y:H*.15, t:'N. Atlantic\nGyre', c:'#93c5fd'},
      {x:W*.5,  y:H*.58, t:'Equatorial\nCurrent', c:'#6ee7b7'},
      {x:W*.75, y:H*.8,  t:'Deep water\nsinking', c:'rgba(255,255,255,0.5)'},
    ];
    labels.forEach(l => {
      ctx.fillStyle = l.c; ctx.font = 'bold 9px Nunito,sans-serif'; ctx.textAlign = 'center';
      l.t.split('\n').forEach((line, i) => ctx.fillText(line, l.x, l.y + i*12));
    });

    // AMOC strength indicator
    const amoc = Math.max(0, 100 - warm*8);
    ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(W-90, 8, 82, 30);
    ctx.fillStyle='rgba(255,255,255,0.3)'; ctx.fillRect(W-86, 22, 74, 10);
    ctx.fillStyle=amoc>60?'#34d399':amoc>30?'#f59e0b':'#ef4444';
    ctx.fillRect(W-86, 22, 74*(amoc/100), 10);
    ctx.fillStyle='#fff'; ctx.font='bold 9px Nunito,sans-serif'; ctx.textAlign='center';
    ctx.fillText('AMOC strength', W-49, 19);

    const surfT = (28 - warm*0.4).toFixed(1);
    pFlow.set(Math.round(wind*3)+' Sv'); pTemp.set(surfT+'°C'); pAMOC.set(Math.round(amoc)+'%');
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simVolcano(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('volcano', lvl);
  const pPres = pill(L.pres); const pVEI = pill(L.vei); const pPhase = pill(L.phase);
  pRow.appendChild(pPres.el); pRow.appendChild(pVEI.el); pRow.appendChild(pPhase.el);
  const rVisc  = mkRange(ctrl, L.visc, 1, 10, 4, 1, color);
  const rRecharge = mkRange(ctrl, L.recharge, 1, 10, 4, 1, color);
  const bErupt = mkBtn('💥 ' + L.erupt, true, color);
  ctrl.appendChild(bErupt);

  let pressure = 20, erupting = false, eruptT = 0, eruptPower = 0;
  let particles = [], ashCloud = [];
  let phase = 'Recharging';

  bErupt.addEventListener('click', () => {
    if (!erupting) { erupting = true; eruptT = 0; eruptPower = Math.min(100,pressure); pressure = 5; phase = 'Erupting!'; }
  });

  const S = SIMS.volcano = { raf: null };
  let t = 0;
  const cx = W/2, baseY = H-30;
  const volcH = 140, volcW = 110;

  function frame() {
    t++;
    // pressure build-up
    if (!erupting) {
      pressure += 0.06 * rRecharge.val;
      if (pressure >= 100) { erupting = true; eruptT = 0; eruptPower = 100; pressure = 5; phase = 'Erupting!'; }
      else phase = pressure > 70 ? 'Critical!' : pressure > 40 ? 'Pressurising' : 'Recharging';
    } else {
      eruptT++;
      pressure = Math.max(5, pressure + 0.1 * rRecharge.val);
      if (eruptT > 200) { erupting = false; ashCloud = []; particles = []; phase = 'Cooling'; }
    }

    // spawn eruption particles
    const visc = rVisc.val;
    if (erupting && t % Math.max(1, Math.round(visc/2)) === 0) {
      const explosive = visc > 5;
      for (let i = 0; i < (explosive ? 3 : 1); i++) {
        particles.push({
          x: cx + (Math.random()-.5)*10,
          y: baseY - volcH,
          vx: (Math.random()-.5) * (explosive ? 5 : 2),
          vy: -(4 + Math.random()*6) * (explosive ? 1.4 : 0.8),
          r: 2 + Math.random()*4,
          life: 80 + Math.random()*60,
          age: 0,
          type: explosive ? 'ash' : 'lava',
          col: explosive ? `hsl(${20+Math.random()*20},60%,${40+Math.random()*20}%)` : `hsl(${15+Math.random()*20},90%,${50+Math.random()*20}%)`
        });
      }
    }

    ctx.clearRect(0, 0, W, H);
    const heat = pressure/100;
    const e = erupting ? Math.min(1, eruptT/100) : 0;      // eruption darkening

    // sky - calm blue when idle, charcoal/ember when erupting (never green)
    const lc=(a,b,f)=>`rgb(${Math.round(a[0]+(b[0]-a[0])*f)},${Math.round(a[1]+(b[1]-a[1])*f)},${Math.round(a[2]+(b[2]-a[2])*f)})`;
    const skyG = ctx.createLinearGradient(0,0,0,baseY+20);
    skyG.addColorStop(0, lc([122,167,212],[24,18,26],e));
    skyG.addColorStop(1, lc([222,196,158],[60,22,16],e));
    ctx.fillStyle = skyG; ctx.fillRect(0,0,W,H);

    // ground
    ctx.fillStyle = '#241f1c'; ctx.fillRect(0, baseY+20, W, H-baseY-20);

    // volcano cone
    ctx.beginPath();
    ctx.moveTo(cx-volcW*1.4, baseY+20);
    ctx.lineTo(cx-volcW*.4, baseY-volcH*.35);
    ctx.quadraticCurveTo(cx-volcW*.12, baseY-volcH, cx, baseY-volcH);
    ctx.quadraticCurveTo(cx+volcW*.12, baseY-volcH, cx+volcW*.4, baseY-volcH*.35);
    ctx.lineTo(cx+volcW*1.4, baseY+20);
    ctx.closePath();
    ctx.fillStyle = '#44403c'; ctx.fill();
    ctx.strokeStyle = '#57534e'; ctx.lineWidth = 1.5; ctx.stroke();

    // ── cutaway cross-section: magma chamber + conduit ──
    const condTopY = baseY-volcH+8, condBotY = baseY+6;
    // chamber glow halo
    const halo = ctx.createRadialGradient(cx, condBotY+14, 0, cx, condBotY+14, 90);
    halo.addColorStop(0, `rgba(255,140,30,${0.3+heat*0.5})`);
    halo.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = halo; ctx.beginPath(); ctx.arc(cx, condBotY+14, 90, 0, Math.PI*2); ctx.fill();
    // magma rises in the conduit with pressure
    const magmaTopY = condBotY - (condBotY-condTopY) * Math.min(1, pressure/100);
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx-7, condBotY); ctx.lineTo(cx-4.5, condTopY);
    ctx.lineTo(cx+4.5, condTopY); ctx.lineTo(cx+7, condBotY); ctx.closePath();
    ctx.fillStyle = '#160f0c'; ctx.fill();             // empty conduit
    ctx.clip();
    const mg = ctx.createLinearGradient(0, condBotY, 0, condTopY);
    mg.addColorStop(0, 'hsl(18,100%,52%)'); mg.addColorStop(1, `hsl(45,100%,${60+heat*12}%)`);
    ctx.fillStyle = mg; ctx.fillRect(cx-8, magmaTopY, 16, condBotY-magmaTopY);
    ctx.restore();
    // chamber body
    ctx.save(); ctx.shadowColor='rgba(255,120,20,0.8)'; ctx.shadowBlur=24;
    ctx.beginPath(); ctx.ellipse(cx, condBotY+16, 62, 19, 0, 0, Math.PI*2);
    const cg = ctx.createRadialGradient(cx, condBotY+10, 4, cx, condBotY+16, 62);
    cg.addColorStop(0, `hsl(48,100%,${62+heat*14}%)`); cg.addColorStop(0.55, 'hsl(26,100%,54%)'); cg.addColorStop(1, 'hsl(12,88%,34%)');
    ctx.fillStyle = cg; ctx.fill(); ctx.restore();

    // crater glow
    const craterGlow = ctx.createRadialGradient(cx, condTopY, 0, cx, condTopY, 20+pressure*.15);
    craterGlow.addColorStop(0, `rgba(255,${80+pressure},0,${0.4+pressure/150})`);
    craterGlow.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = craterGlow; ctx.beginPath(); ctx.arc(cx, condTopY, 20+pressure*.15, 0, Math.PI*2); ctx.fill();

    // update & draw particles
    for (let i = particles.length-1; i >= 0; i--) {
      const p = particles[i];
      p.age++; p.vx *= 0.98; p.vy += 0.12; p.x += p.vx; p.y += p.vy;
      if (p.age > p.life || p.y > baseY+10) { particles.splice(i,1); continue; }
      const alpha = 1 - p.age/p.life;
      if (p.type==='lava'){
        ctx.save(); ctx.shadowColor='rgba(255,90,0,0.9)'; ctx.shadowBlur=10;
        ctx.globalAlpha=alpha; ctx.fillStyle=p.col;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2); ctx.fill(); ctx.restore();
      } else {
        ctx.globalAlpha=alpha*.8; ctx.fillStyle=`rgba(120,108,100,1)`;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2); ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    // pressure gauge
    ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(12,12,16,H*.55);
    const gaugeH = (H*.55)*(pressure/100);
    const gc = pressure>70?'#ef4444':pressure>40?'#f59e0b':'#34d399';
    ctx.fillStyle=gc; ctx.fillRect(12, 12+H*.55-gaugeH, 16, gaugeH);
    ctx.strokeStyle='rgba(255,255,255,0.3)'; ctx.strokeRect(12,12,16,H*.55);
    ctx.fillStyle='#fff'; ctx.font='8px Nunito,sans-serif'; ctx.textAlign='center';
    ctx.fillText('P', 20, 10);

    // VEI estimate
    const vei = Math.min(8, Math.round((eruptPower/100)*visc/1.5));
    pPres.set(Math.round(pressure)+'%'); pVEI.set(erupting?'VEI '+vei:'-'); pPhase.set(phase);
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simChem(container,color,lvl){
  const W=getSimWidth(container),H=280;
  const {canvas,ctx}=mkCanvas(container,W,H);
  const ctrl=mkCtrl(container);
  const pRow=mkPills(container);
  const L=simLabels('chem',lvl);
  const pMol=pill(L.mols); const pTemp=pill(L.t);
  pRow.appendChild(pMol.el); pRow.appendChild(pTemp.el);
  const rT=mkRange(ctrl,L.temp,1,10,5,1,color);
  const bReset=mkBtn('↺ '+L.reset,true,color);
  ctrl.appendChild(bReset);
  const ATOMS=[];
  const TYPES=[
    {sym:'H',r:10,col:'#ef4444'},{sym:'O',r:14,col:'#3b82f6'},
    {sym:'C',r:13,col:'#6b7280'},{sym:'N',r:12,col:'#8b5cf6'}
  ];
  function init(){
    ATOMS.length=0;
    for(let i=0;i<28;i++){
      const t=TYPES[Math.floor(Math.random()*TYPES.length)];
      ATOMS.push({x:t.r+Math.random()*(W-2*t.r),y:t.r+Math.random()*(H-2*t.r),
        vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,
        r:t.r,sym:t.sym,col:t.col,bond:null});
    }
  }
  bReset.addEventListener('click',init);
  init();
  const S=SIMS.chem={raf:null};
  let molCount=0;
  function frame(){
    const spd=rT.val/5;
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#0f172a'; ctx.fillRect(0,0,W,H);
    // draw bonds
    ATOMS.forEach(a=>{
      if(a.bond&&a.bond>a){
        ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(a.bond.x,a.bond.y);
        ctx.strokeStyle='rgba(255,255,255,0.3)';ctx.lineWidth=2;ctx.stroke();
      }
    });
    // move & draw
    molCount=0;
    ATOMS.forEach(a=>{
      a.vx+=((Math.random()-.5)*0.4)*spd;
      a.vy+=((Math.random()-.5)*0.4)*spd;
      const maxV=4*spd;
      const v=Math.sqrt(a.vx*a.vx+a.vy*a.vy);
      if(v>maxV){a.vx=a.vx/v*maxV;a.vy=a.vy/v*maxV;}
      if(a.bond){a.x+=(a.bond.x+(a.r+a.bond.r+2)*Math.cos(Math.atan2(a.y-a.bond.y,a.x-a.bond.x))-a.x)*.12+a.vx*.15;}
      else{a.x+=a.vx;a.y+=a.vy;}
      if(a.x<a.r){a.x=a.r;a.vx=Math.abs(a.vx);}
      if(a.x>W-a.r){a.x=W-a.r;a.vx=-Math.abs(a.vx);}
      if(a.y<a.r){a.y=a.r;a.vy=Math.abs(a.vy);}
      if(a.y>H-a.r){a.y=H-a.r;a.vy=-Math.abs(a.vy);}
      // bonding
      if(!a.bond&&spd<4){
        for(const b of ATOMS){
          if(b===a||b.bond)continue;
          const dx=b.x-a.x,dy=b.y-a.y,d=Math.sqrt(dx*dx+dy*dy);
          if(d<(a.r+b.r+8)&&Math.random()<0.01*(5-spd)){a.bond=b;b.bond=a;break;}
        }
      } else if(a.bond&&Math.random()<0.005*spd){a.bond.bond=null;a.bond=null;}
      // draw
      ctx.beginPath();ctx.arc(a.x,a.y,a.r,0,Math.PI*2);
      ctx.fillStyle=a.col;ctx.fill();
      ctx.fillStyle='#fff';ctx.font=`bold ${Math.round(a.r)}px Nunito,sans-serif`;
      ctx.textAlign='center';ctx.textBaseline='middle';
      ctx.fillText(a.sym,a.x,a.y);
      if(a.bond)molCount++;
    });
    pMol.set(Math.floor(molCount/2)+' bonds');
    pTemp.set(Math.round(rT.val*100)+'K');
    S.raf=requestAnimationFrame(frame);
  }
  frame();
}

function simElectrochem(container, color, lvl) {
  const W = getSimWidth(container), H = 300;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('electrochem', lvl);
  const pV    = pill(L.volts); const pQ = pill(L.soc); const pMode = pill(L.mode);
  pRow.appendChild(pV.el); pRow.appendChild(pQ.el); pRow.appendChild(pMode.el);
  const rLoad    = mkRange(ctrl, L.load, 1, 10, 4, 1, color);
  const bDischarge = mkBtn('▶ ' + L.discharge, true, color);
  const bCharge    = mkBtn('⚡ ' + L.charge);
  const bReset     = mkBtn('↺ ' + L.reset);
  ctrl.appendChild(bDischarge); ctrl.appendChild(bCharge); ctrl.appendChild(bReset);

  let soc = 1.0;        // state of charge 0–1
  let mode = 'idle';    // idle | discharge | charge
  let ions = [];        // animated ion particles
  let t = 0;

  function initIons() {
    ions = [];
    for (let i = 0; i < 28; i++)
      ions.push({ x: 0.2*W + Math.random()*0.6*W, y: 60 + Math.random()*(H-120),
        vx:0, vy:0, side: Math.random()<0.5?'L':'R', phase: Math.random()*Math.PI*2 });
  }
  function reset() { soc=1.0; mode='idle'; initIons(); }
  bDischarge.addEventListener('click', () => mode='discharge');
  bCharge.addEventListener('click',    () => mode='charge');
  bReset.addEventListener('click', reset);
  reset();

  const S = SIMS.electrochem = { raf: null };

  function frame() {
    t++;
    // update SOC
    const rate = rLoad.val * 0.0008;
    if (mode==='discharge') { soc = Math.max(0, soc - rate); if (soc<=0) mode='idle'; }
    if (mode==='charge')    { soc = Math.min(1, soc + rate*0.7); if (soc>=1) mode='idle'; }

    // Nernst-like voltage: E = E0 - (0.059/n)*log((1-soc)/soc)
    const E0 = 3.7, n = 1;
    const ratio = Math.max(0.001, (1-soc)/Math.max(0.001,soc));
    const voltage = Math.max(2.5, Math.min(4.2, E0 - (0.059/n)*Math.log10(ratio)));

    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);

    // electrodes
    const anodeX = 80, cathodeX = W-80, elecH = H-80, elecW = 36, elecY = 40;
    // anode (graphite - discharge: Li leaves)
    const anodeCol = mode==='discharge'?'#6366f1':'#4338ca';
    ctx.fillStyle = anodeCol;
    ctx.fillRect(anodeX - elecW/2, elecY, elecW, elecH);
    ctx.fillStyle='rgba(255,255,255,0.08)';
    for(let i=0;i<8;i++) ctx.fillRect(anodeX-elecW/2+2, elecY+10+i*(elecH-20)/8, elecW-4, 4);
    ctx.fillStyle='#a5b4fc'; ctx.font='bold 10px Nunito,sans-serif'; ctx.textAlign='center';
    ctx.fillText('ANODE', anodeX, elecY-8);
    ctx.fillText('(Graphite)', anodeX, elecY-18);

    // cathode (LiCoO2)
    const cathodeCol = mode==='charge'?'#f59e0b':'#d97706';
    ctx.fillStyle = cathodeCol;
    ctx.fillRect(cathodeX - elecW/2, elecY, elecW, elecH);
    ctx.fillStyle='rgba(255,255,255,0.08)';
    for(let i=0;i<8;i++) ctx.fillRect(cathodeX-elecW/2+2, elecY+10+i*(elecH-20)/8, elecW-4, 4);
    ctx.fillStyle='#fcd34d'; ctx.font='bold 10px Nunito,sans-serif'; ctx.textAlign='center';
    ctx.fillText('CATHODE', cathodeX, elecY-8);
    ctx.fillText('(LiCoO₂)', cathodeX, elecY-18);

    // electrolyte region
    ctx.fillStyle='rgba(14,165,233,0.07)';
    ctx.fillRect(anodeX+elecW/2, elecY, cathodeX-anodeX-elecW, elecH);
    ctx.fillStyle='rgba(14,165,233,0.3)'; ctx.font='10px Nunito,sans-serif'; ctx.textAlign='center';
    ctx.fillText('Electrolyte (LiPF₆)', W/2, elecY+elecH/2);

    // external circuit (wire + bulb)
    const wireY = elecY - 22;
    ctx.strokeStyle='rgba(255,255,255,0.4)'; ctx.lineWidth=3;
    ctx.beginPath();
    ctx.moveTo(anodeX, elecY); ctx.lineTo(anodeX, wireY);
    ctx.lineTo(W/2-18, wireY); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cathodeX, elecY); ctx.lineTo(cathodeX, wireY);
    ctx.lineTo(W/2+18, wireY); ctx.stroke();
    // bulb/charger icon
    const bulbGlow = mode==='discharge' ? Math.min(1, soc+0.1) : 0;
    const chargeGlow = mode==='charge' ? 0.8 : 0;
    ctx.beginPath(); ctx.arc(W/2, wireY, 14, 0, Math.PI*2);
    ctx.fillStyle = mode==='charge' ? `rgba(251,191,36,${0.3+chargeGlow*0.5})` : `rgba(253,224,71,${0.1+bulbGlow*0.7})`;
    ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.5)'; ctx.lineWidth=1.5; ctx.stroke();
    ctx.fillStyle='#fff'; ctx.font='bold 11px Nunito,sans-serif'; ctx.textAlign='center';
    ctx.fillText(mode==='charge'?'⚡':'💡', W/2, wireY+4);

    // electron flow arrows on wire
    if (mode !== 'idle') {
      const dir = mode==='discharge' ? 1 : -1;
      const arrowT = (t*0.03*dir + 10) % 1;
      const ax = anodeX + (W/2-14 - anodeX) * arrowT;
      ctx.beginPath(); ctx.arc(ax, wireY, 4, 0, Math.PI*2);
      ctx.fillStyle='#60a5fa'; ctx.fill();
      ctx.fillStyle='#60a5fa'; ctx.font='8px Nunito,sans-serif'; ctx.textAlign='center';
      ctx.fillText('e⁻', ax, wireY-8);
    }

    // ion particles
    ions.forEach(ion => {
      const dir = mode==='discharge' ? 1 : -1; // discharge: anode→cathode
      ion.phase += 0.03 * rLoad.val * Math.abs(dir);
      const prog = (Math.sin(ion.phase)*0.5+0.5);
      const tx = mode==='idle' ? ion.x :
        dir > 0 ? anodeX+elecW/2+20 + prog*(cathodeX-elecW/2-20 - (anodeX+elecW/2+20))
                : cathodeX-elecW/2-20 - prog*(cathodeX-elecW/2-20 - (anodeX+elecW/2+20));
      const ty = elecY + 20 + Math.sin(ion.phase*1.3+ion.side==='L'?0:Math.PI)*(elecH-40)*0.4 + elecH*0.3;
      ctx.beginPath(); ctx.arc(tx, ty, 5, 0, Math.PI*2);
      ctx.fillStyle='#34d399'; ctx.fill();
      ctx.fillStyle='#fff'; ctx.font='bold 7px Nunito,sans-serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('Li⁺', tx, ty); ctx.textBaseline='alphabetic';
    });

    // SOC bar
    ctx.fillStyle='rgba(255,255,255,0.1)'; ctx.fillRect(10, H-22, W-20, 12);
    ctx.fillStyle=soc>0.4?'#34d399':soc>0.2?'#f59e0b':'#ef4444';
    ctx.fillRect(10, H-22, (W-20)*soc, 12);
    ctx.fillStyle='#fff'; ctx.font='9px Nunito,sans-serif'; ctx.textAlign='left';
    ctx.fillText('State of Charge: '+Math.round(soc*100)+'%', 14, H-12);

    pV.set(voltage.toFixed(2)+' V');
    pQ.set(Math.round(soc*100)+'%');
    pMode.set(mode==='discharge'?'Discharging':mode==='charge'?'Charging':'Idle');
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

function simKinetics(container, color, lvl) {
  const C=(typeof color==='string'&&color[0]==='#')?color:'#f59e0b';
  const W = getSimWidth(container), H = 384;
  const { canvas, ctx } = mkCanvas(container, W, H);
  const ctrl = mkCtrl(container);
  const pRow = mkPills(container);
  const L = simLabels('kinetics', lvl);
  const pReact = pill(L.react); const pProd = pill(L.prod); const pRate = pill(L.rate);
  pRow.appendChild(pReact.el); pRow.appendChild(pProd.el); pRow.appendChild(pRate.el);
  const rTemp  = mkRange(ctrl, L.temp, 200, 800, 400, 10, color);
  const rEa    = mkRange(ctrl, L.ea, 10, 100, 50, 5, color);
  const bCat   = mkBtn('⚗️ ' + L.cat, true, color);
  const bReset = mkBtn('↺ ' + L.reset);
  ctrl.appendChild(bCat); ctrl.appendChild(bReset);

  // Reaction vessel and energy chart get their own boxes — molecules never stray
  // into the graph, and the graph never sits under bouncing dots.
  const VES={x:12,y:44,w:W-24,h:Math.round(H*0.40)};
  const CH={x:12,y:44+Math.round(H*0.40)+48,w:W-24,h:H-(44+Math.round(H*0.40)+48)-12};
  const R_GAS=8.314, A_PRE=1e6, DH=12000;   // exothermic by 12 kJ/mol: R ⇌ P

  let molecules=[], catActive=false;
  function initMolecules(){
    molecules=[];catActive=false;bCat.textContent='⚗️ '+L.cat;
    for(let i=0;i<60;i++)molecules.push({
      x:VES.x+8+Math.random()*(VES.w-16), y:VES.y+8+Math.random()*(VES.h-16),
      vx:(Math.random()-.5)*2, vy:(Math.random()-.5)*2, type:'R', r:6, flash:0
    });
  }
  bCat.addEventListener('click',()=>{catActive=!catActive;bCat.textContent=catActive?('✕ '+L.cat):('⚗️ '+L.cat);});
  bReset.addEventListener('click',initMolecules);
  initMolecules();

  const S = SIMS.kinetics = { raf: null };
  function rr(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}
  function panel(b,title){
    ctx.fillStyle='rgba(255,255,255,0.045)';rr(b.x,b.y,b.w,b.h,10);ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.18)';ctx.lineWidth=1;ctx.stroke();
    ctx.fillStyle='rgba(226,232,240,0.75)';ctx.font='bold 11px system-ui';ctx.textAlign='left';
    ctx.fillText(title,b.x+2,b.y-7);
  }

  function frame() {
    const T=rTemp.val, Ea=rEa.val*1000;
    // A catalyst lowers the transition state, so BOTH barriers drop by the same
    // amount — which is why it never changes where the equilibrium sits.
    const drop=catActive?Ea*0.55:0;
    const EaF=Math.max(1000,Ea-drop), EaR=Math.max(1000,Ea+DH-drop);
    const kF=A_PRE*Math.exp(-EaF/(R_GAS*T)), kR=A_PRE*Math.exp(-EaR/(R_GAS*T));
    // scale both rates by the SAME factor: clamping only the forward one used to
    // fake an equilibrium that the chemistry does not have
    const sc=Math.min(1,0.30/Math.max(kF,kR,1e-30));
    const pF=kF*sc, pR=kR*sc;
    const K=Math.exp(DH/(R_GAS*T));                 // = kF/kR, catalyst-independent
    const eqFrac=Math.sqrt(K)/(1+Math.sqrt(K));      // 2R ⇌ 2P at equal numbers

    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#0f172a';ctx.fillRect(0,0,W,H);

    panel(VES,'Reaction vessel — ' + (catActive?'catalysed':'uncatalysed'));
    panel(CH,'Energy profile');

    // molecules stay inside the vessel
    const spd=Math.sqrt(T/300);
    molecules.forEach(m=>{
      m.x+=m.vx*spd;m.y+=m.vy*spd;
      if(m.x<VES.x+m.r){m.x=VES.x+m.r;m.vx*=-1;} if(m.x>VES.x+VES.w-m.r){m.x=VES.x+VES.w-m.r;m.vx*=-1;}
      if(m.y<VES.y+m.r){m.y=VES.y+m.r;m.vy*=-1;} if(m.y>VES.y+VES.h-m.r){m.y=VES.y+VES.h-m.r;m.vy*=-1;}
      m.vx+=(Math.random()-.5)*0.15*spd;m.vy+=(Math.random()-.5)*0.15*spd;
      const v=Math.hypot(m.vx,m.vy),maxV=3*spd;
      if(v>maxV){m.vx=m.vx/v*maxV;m.vy=m.vy/v*maxV;}
      if(m.flash>0)m.flash-=0.06;
    });

    // collisions, forward AND reverse — this is what makes it an equilibrium
    for(let i=0;i<molecules.length;i++){
      const a=molecules[i];
      for(let j=i+1;j<molecules.length;j++){
        const b=molecules[j];
        if(a.type!==b.type)continue;
        const dx=b.x-a.x, dy=b.y-a.y;
        if(dx*dx+dy*dy>(a.r*2.5)**2)continue;
        const p=a.type==='R'?pF:pR;
        if(Math.random()<p){
          const to=a.type==='R'?'P':'R';
          a.type=to;b.type=to;a.flash=1;b.flash=1;
          a.vx*=-1;b.vx*=-1;
        }
        break;
      }
    }

    molecules.forEach(m=>{
      if(m.flash>0){
        ctx.beginPath();ctx.arc(m.x,m.y,m.r+7*m.flash,0,Math.PI*2);
        ctx.fillStyle='rgba(255,255,255,'+(0.28*m.flash)+')';ctx.fill();
      }
      ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);
      ctx.fillStyle=m.type==='R'?'#6366f1':'#f59e0b';ctx.fill();
      ctx.fillStyle='#fff';ctx.font='bold 7px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';
      ctx.fillText(m.type,m.x,m.y);ctx.textBaseline='alphabetic';
    });
    if(catActive){
      ctx.strokeStyle='rgba(52,211,153,0.55)';ctx.lineWidth=1.5;ctx.setLineDash([6,4]);
      rr(VES.x+3,VES.y+3,VES.w-6,VES.h-6,8);ctx.stroke();ctx.setLineDash([]);
    }

    const nR=molecules.filter(m=>m.type==='R').length, nP=molecules.length-nR;
    // composition bar between the two panels
    const bx=VES.x,by=VES.y+VES.h+10,bw=VES.w,bh=14;
    ctx.fillStyle='#6366f1';ctx.fillRect(bx,by,bw*nR/molecules.length,bh);
    ctx.fillStyle='#f59e0b';ctx.fillRect(bx+bw*nR/molecules.length,by,bw*nP/molecules.length,bh);
    ctx.strokeStyle='rgba(255,255,255,0.25)';ctx.lineWidth=1;ctx.strokeRect(bx,by,bw,bh);
    // where the equilibrium should land, marked on the same bar
    const eqX=bx+bw*(1-eqFrac);
    ctx.strokeStyle='#fff';ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(eqX,by-5);ctx.lineTo(eqX,by+bh+5);ctx.stroke();
    ctx.fillStyle='rgba(255,255,255,0.85)';ctx.font='9px system-ui';
    ctx.textAlign=eqX>bx+bw*0.8?'right':(eqX<bx+bw*0.2?'left':'center');
    ctx.fillText('predicted equilibrium: '+Math.round(eqFrac*100)+'% P',eqX,by+bh+11);

    // ── energy profile ──
    const baseY=CH.y+CH.h-16, reactY=baseY-26, prodY=baseY-26+ (DH/1000)*0.9;
    const tsFull=CH.y+16, tsY=catActive?CH.y+16+(CH.h*0.34):tsFull;
    const x0=CH.x+14, x1=CH.x+CH.w-14, midX=(x0+x1)/2;
    ctx.strokeStyle='rgba(255,255,255,0.25)';ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(x0-4,CH.y+10);ctx.lineTo(x0-4,baseY+6);ctx.lineTo(x1,baseY+6);ctx.stroke();
    ctx.fillStyle='rgba(255,255,255,0.45)';ctx.font='9px system-ui';ctx.textAlign='left';
    ctx.save();ctx.translate(x0-9,CH.y+52);ctx.rotate(-Math.PI/2);ctx.fillText('energy',0,0);ctx.restore();
    ctx.textAlign='right';ctx.fillText('reaction progress',x1,baseY+16);
    function path(peak,col,dash){
      ctx.beginPath();ctx.moveTo(x0,reactY);
      ctx.bezierCurveTo(midX-50,reactY,midX-26,peak,midX,peak);
      ctx.bezierCurveTo(midX+26,peak,midX+50,prodY,x1,prodY);
      ctx.strokeStyle=col;ctx.lineWidth=2.2;ctx.setLineDash(dash?[5,3]:[]);ctx.stroke();ctx.setLineDash([]);
    }
    path(tsFull,catActive?'rgba(99,102,241,0.35)':'rgba(129,140,248,0.9)',false);
    if(catActive)path(tsY,'#34d399',true);
    const useY=catActive?tsY:tsFull;
    // barrier arrows, forward and reverse
    ctx.strokeStyle='rgba(255,255,255,0.5)';ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(midX-58,reactY);ctx.lineTo(midX-58,useY);ctx.stroke();
    ctx.beginPath();ctx.moveTo(midX+58,prodY);ctx.lineTo(midX+58,useY);ctx.stroke();
    ctx.fillStyle='#a5b4fc';ctx.font='9px system-ui';ctx.textAlign='right';
    ctx.fillText('Ea→ '+Math.round(EaF/1000)+' kJ',midX-62,(reactY+useY)/2);
    ctx.fillStyle='#fcd34d';ctx.textAlign='left';
    ctx.fillText('←Ea '+Math.round(EaR/1000)+' kJ',midX+62,(prodY+useY)/2);
    ctx.fillStyle='#a5b4fc';ctx.textAlign='left';ctx.fillText('R',x0,reactY-6);
    ctx.fillStyle='#fcd34d';ctx.textAlign='right';ctx.fillText('P',x1,prodY-6);
    ctx.strokeStyle='rgba(255,255,255,0.22)';ctx.setLineDash([3,3]);
    ctx.beginPath();ctx.moveTo(x0,reactY);ctx.lineTo(x1,reactY);ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle='rgba(255,255,255,0.55)';ctx.textAlign='center';
    ctx.fillText('ΔH = −'+(DH/1000)+' kJ/mol (exothermic)',midX,prodY+16);
    ctx.fillStyle='rgba(255,255,255,0.75)';ctx.font='bold 10px system-ui';ctx.textAlign='right';
    ctx.fillText('K = k→/k← = '+(K>=100?K.toExponential(1):K.toFixed(1)),x1,CH.y+16);

    pReact.set(nR); pProd.set(nP);
    pRate.set('k→ '+kF.toExponential(1)+' · k← '+kR.toExponential(1));
    S.raf = requestAnimationFrame(frame);
  }
  frame();
}

